var e=JSON.parse(`[{"id":16000,"term":"about","meaning":"~에 대하여; 막 ~하려는 (about to)","partOfSpeech":"prep.","example":"We were about to leave when the phone rang.","exampleTranslation":"우리가 막 떠나려던 참에 전화가 울렸어요.","level":1,"category":"빈도 학습"},{"id":16001,"term":"above","meaning":"~보다 위에; 무엇보다도 (above all)","partOfSpeech":"prep.","example":"Above all, remember to stay calm during the exam.","exampleTranslation":"무엇보다도, 시험 중에 침착함을 유지하는 것을 기억하세요.","level":1,"category":"빈도 학습"},{"id":16002,"term":"accent","meaning":"억양; 강세","partOfSpeech":"n.","example":"She has a strong French accent when she speaks English.","exampleTranslation":"그녀는 영어를 말할 때 강한 프랑스 억양이 있어요.","level":1,"category":"빈도 학습"},{"id":16003,"term":"ace","meaning":"(시험 등을) 완벽히 해내다","partOfSpeech":"v.","example":"He can ace any exam without much studying.","exampleTranslation":"그는 별로 공부하지 않고도 어떤 시험이든 완벽히 해낼 수 있어요.","level":1,"category":"빈도 학습"},{"id":16004,"term":"all","meaning":"모든; 줄곧 (all along)","partOfSpeech":"adj.","example":"I knew all along that she was hiding something.","exampleTranslation":"나는 그녀가 뭔가를 숨기고 있다는 것을 처음부터 계속 알고 있었어요.","level":1,"category":"빈도 학습"},{"id":16005,"term":"also","meaning":"또한; ~도","partOfSpeech":"adv.","example":"She is not only smart but also very kind.","exampleTranslation":"그녀는 똑똑할 뿐만 아니라 매우 친절하기도 해요.","level":1,"category":"빈도 학습"},{"id":16006,"term":"although","meaning":"비록 ~이지만","partOfSpeech":"conj.","example":"Although it was raining, they went for a walk.","exampleTranslation":"비가 내리고 있었지만, 그들은 산책하러 나갔어요.","level":1,"category":"빈도 학습"},{"id":16007,"term":"another","meaning":"또 다른; 하나 더","partOfSpeech":"adj.","example":"Could I have another cup of coffee, please?","exampleTranslation":"커피 한 잔 더 주시겠어요?","level":1,"category":"빈도 학습"},{"id":16008,"term":"any","meaning":"어떤; 조금도 (부정문에서)","partOfSpeech":"adj.","example":"There is hardly any milk left in the fridge.","exampleTranslation":"냉장고에 우유가 거의 남아 있지 않아요.","level":1,"category":"빈도 학습"},{"id":16009,"term":"away","meaning":"떨어져; 멀리","partOfSpeech":"adv.","example":"The beach is just a short walk away from our hotel.","exampleTranslation":"해변은 저희 호텔에서 걸어서 가까운 거리에 있어요.","level":1,"category":"빈도 학습"},{"id":16010,"term":"back","meaning":"뒤로; 다시","partOfSpeech":"adv.","example":"He promised to call her back after the meeting.","exampleTranslation":"그는 회의가 끝난 후 그녀에게 다시 전화하겠다고 약속했어요.","level":1,"category":"빈도 학습"},{"id":16011,"term":"because","meaning":"왜냐하면; ~때문에","partOfSpeech":"conj.","example":"Just because it's raining doesn't mean we should cancel the trip.","exampleTranslation":"비가 온다고 해서 여행을 취소해야 하는 건 아니에요.","level":1,"category":"빈도 학습"},{"id":16012,"term":"below","meaning":"~아래에; 이하","partOfSpeech":"prep.","example":"The temperature dropped below zero last night.","exampleTranslation":"어젯밤 기온이 영하로 떨어졌어요.","level":1,"category":"빈도 학습"},{"id":16013,"term":"billion","meaning":"10억","partOfSpeech":"n.","example":"A billion consists of a one followed by nine zeros.","exampleTranslation":"10억은 1 뒤에 0이 아홉 개 오는 수예요.","level":1,"category":"빈도 학습"},{"id":16014,"term":"boring","meaning":"지루한","partOfSpeech":"adj.","example":"The lecture was so boring that several students fell asleep.","exampleTranslation":"강의가 너무 지루해서 몇몇 학생들이 잠들어 버렸어요.","level":1,"category":"빈도 학습"},{"id":16015,"term":"amuse","meaning":"즐겁게 하다; 재미있게 하다","partOfSpeech":"v.","example":"The clown's silly tricks amuse the children at every party.","exampleTranslation":"그 광대의 우스꽝스러운 묘기는 파티마다 아이들을 즐겁게 해줘요.","level":2,"category":"빈도 학습"},{"id":16016,"term":"angel","meaning":"천사","partOfSpeech":"n.","example":"The little girl looked like an angel in her white dress.","exampleTranslation":"그 어린 소녀는 하얀 드레스를 입고 천사처럼 보였어요.","level":2,"category":"빈도 학습"},{"id":16017,"term":"both","meaning":"둘 다","partOfSpeech":"adj.","example":"Both my sister and I enjoy hiking on weekends.","exampleTranslation":"제 여동생과 저 둘 다 주말에 하이킹하는 것을 즐겨요.","level":2,"category":"빈도 학습"},{"id":16018,"term":"bush","meaning":"덤불; 관목","partOfSpeech":"n.","example":"A small rabbit hid behind the bush in the garden.","exampleTranslation":"작은 토끼가 정원의 덤불 뒤에 숨었어요.","level":2,"category":"빈도 학습"},{"id":16019,"term":"christmas","meaning":"크리스마스","partOfSpeech":"n.","example":"We always decorate a big tree for Christmas.","exampleTranslation":"우리는 크리스마스를 위해 항상 큰 나무를 장식해요.","level":2,"category":"빈도 학습"},{"id":16020,"term":"darling","meaning":"사랑스러운; 소중한","partOfSpeech":"adj.","example":"She kissed her darling baby goodnight.","exampleTranslation":"그녀는 사랑스러운 아기에게 잘 자라고 입을 맞췄어요.","level":2,"category":"빈도 학습"},{"id":16021,"term":"definite","meaning":"확실한; 명확한","partOfSpeech":"adj.","example":"We need a definite answer by Friday.","exampleTranslation":"우리는 금요일까지 확실한 답변이 필요해요.","level":2,"category":"빈도 학습"},{"id":16022,"term":"each","meaning":"각각의; 서로 (each other)","partOfSpeech":"pron.","example":"The two brothers always help each other with their homework.","exampleTranslation":"그 두 형제는 항상 서로의 숙제를 도와줘요.","level":2,"category":"빈도 학습"},{"id":16023,"term":"eight","meaning":"여덟; 8","partOfSpeech":"adj.","example":"A spider has eight legs.","exampleTranslation":"거미는 다리가 여덟 개예요.","level":2,"category":"빈도 학습"},{"id":16024,"term":"eleven","meaning":"열하나; 11","partOfSpeech":"adj.","example":"There are eleven players on a soccer team.","exampleTranslation":"축구팀에는 11명의 선수가 있어요.","level":2,"category":"빈도 학습"},{"id":16025,"term":"every","meaning":"모든; ~마다","partOfSpeech":"adj.","example":"She calls her mother every single morning without fail.","exampleTranslation":"그녀는 하루도 빠짐없이 매일 아침 어머니께 전화해요.","level":2,"category":"빈도 학습"},{"id":16026,"term":"five","meaning":"다섯; 5","partOfSpeech":"adj.","example":"A standard human hand has five fingers.","exampleTranslation":"보통 사람의 손에는 손가락이 다섯 개 있어요.","level":2,"category":"빈도 학습"},{"id":16027,"term":"four","meaning":"넷; 4","partOfSpeech":"adj.","example":"A car usually has four wheels.","exampleTranslation":"자동차는 보통 바퀴가 네 개 있어요.","level":2,"category":"빈도 학습"},{"id":16028,"term":"friday","meaning":"금요일","partOfSpeech":"n.","example":"The report is due this Friday afternoon.","exampleTranslation":"그 보고서는 이번 주 금요일 오후까지예요.","level":2,"category":"빈도 학습"},{"id":16029,"term":"annoy","meaning":"짜증나게 하다","partOfSpeech":"v.","example":"The loud noise from the construction site continues to annoy me every day.","exampleTranslation":"공사장에서 나는 시끄러운 소음이 매일 저를 계속 짜증나게 해요.","level":3,"category":"빈도 학습"},{"id":16030,"term":"apple","meaning":"사과","partOfSpeech":"n.","example":"She packed an apple in her lunch box.","exampleTranslation":"그녀는 도시락에 사과를 하나 넣었어요.","level":3,"category":"빈도 학습"},{"id":16031,"term":"april","meaning":"4월","partOfSpeech":"n.","example":"Cherry blossoms usually bloom in April.","exampleTranslation":"벚꽃은 보통 4월에 피어요.","level":3,"category":"빈도 학습"},{"id":16032,"term":"asleep","meaning":"잠든","partOfSpeech":"adj.","example":"The baby finally fell asleep after a long day.","exampleTranslation":"아기가 긴 하루를 보낸 후 마침내 잠들었어요.","level":3,"category":"빈도 학습"},{"id":16033,"term":"august","meaning":"8월","partOfSpeech":"n.","example":"We usually go on vacation in August.","exampleTranslation":"우리는 보통 8월에 휴가를 가요.","level":3,"category":"빈도 학습"},{"id":16034,"term":"automatic","meaning":"자동의","partOfSpeech":"adj.","example":"This car has an automatic transmission, so you don't need to shift gears.","exampleTranslation":"이 차는 자동 변속기가 있어서 기어를 바꿀 필요가 없어요.","level":3,"category":"빈도 학습"},{"id":16035,"term":"awake","meaning":"깨어 있는","partOfSpeech":"adj.","example":"He stayed awake all night to finish his project.","exampleTranslation":"그는 프로젝트를 끝내기 위해 밤새 깨어 있었어요.","level":3,"category":"빈도 학습"},{"id":16036,"term":"awkward","meaning":"어색한; 서투른","partOfSpeech":"adj.","example":"There was an awkward silence after his joke fell flat.","exampleTranslation":"그의 농담이 별로였을 때 어색한 침묵이 흘렀어요.","level":3,"category":"빈도 학습"},{"id":16037,"term":"bacon","meaning":"베이컨","partOfSpeech":"n.","example":"The smell of bacon frying filled the kitchen.","exampleTranslation":"베이컨 굽는 냄새가 부엌에 가득 찼어요.","level":3,"category":"빈도 학습"},{"id":16038,"term":"fright","meaning":"놀람; 공포","partOfSpeech":"n.","example":"The sudden noise gave her quite a fright.","exampleTranslation":"갑작스러운 소음이 그녀를 몹시 놀라게 했어요.","level":3,"category":"빈도 학습"},{"id":16039,"term":"grandfather","meaning":"할아버지","partOfSpeech":"n.","example":"My grandfather taught me how to fish when I was young.","exampleTranslation":"제 할아버지는 제가 어렸을 때 낚시하는 법을 가르쳐주셨어요.","level":3,"category":"빈도 학습"},{"id":16040,"term":"here","meaning":"여기에","partOfSpeech":"adv.","example":"We found old coins scattered here and there in the garden.","exampleTranslation":"우리는 정원 여기저기 흩어진 오래된 동전들을 발견했어요.","level":3,"category":"빈도 학습"},{"id":16041,"term":"herself","meaning":"그녀 자신","partOfSpeech":"pron.","example":"She made the birthday cake all by herself.","exampleTranslation":"그녀는 생일 케이크를 순전히 혼자서 만들었어요.","level":3,"category":"빈도 학습"},{"id":16042,"term":"himself","meaning":"그 자신","partOfSpeech":"pron.","example":"He blamed himself for the mistake.","exampleTranslation":"그는 그 실수에 대해 자기 자신을 탓했어요.","level":3,"category":"빈도 학습"},{"id":16043,"term":"how","meaning":"어떻게; 얼마나","partOfSpeech":"adv.","example":"No matter how hard I try, I can't solve this puzzle.","exampleTranslation":"아무리 열심히 노력해도 이 퍼즐을 풀 수가 없어요.","level":3,"category":"빈도 학습"},{"id":16044,"term":"hundred","meaning":"백; 100","partOfSpeech":"adj.","example":"A century lasts exactly a hundred years.","exampleTranslation":"1세기는 정확히 백 년 동안 지속돼요.","level":3,"category":"빈도 학습"},{"id":16045,"term":"if","meaning":"만약 ~라면","partOfSpeech":"conj.","example":"If I were you, I would apologize right away.","exampleTranslation":"내가 너라면, 당장 사과할 거야.","level":3,"category":"빈도 학습"},{"id":16046,"term":"itself","meaning":"그것 자체","partOfSpeech":"pron.","example":"The problem itself is not difficult, but the deadline is tight.","exampleTranslation":"그 문제 자체는 어렵지 않지만, 마감 기한이 촉박해요.","level":3,"category":"빈도 학습"},{"id":16047,"term":"lord","meaning":"영주; 주님","partOfSpeech":"n.","example":"The old castle once belonged to a powerful lord.","exampleTranslation":"그 오래된 성은 한때 강력한 영주의 소유였어요.","level":3,"category":"빈도 학습"},{"id":16048,"term":"abort","meaning":"중단하다; 취소하다","partOfSpeech":"v.","example":"The pilot had to abort the landing due to strong winds.","exampleTranslation":"조종사는 강풍 때문에 착륙을 중단해야 했어요.","level":4,"category":"빈도 학습"},{"id":16049,"term":"absorb","meaning":"흡수하다","partOfSpeech":"v.","example":"Plants absorb sunlight to produce energy.","exampleTranslation":"식물은 에너지를 생산하기 위해 햇빛을 흡수해요.","level":4,"category":"빈도 학습"},{"id":16050,"term":"banana","meaning":"바나나","partOfSpeech":"n.","example":"He sliced a banana into his morning cereal.","exampleTranslation":"그는 아침 시리얼에 바나나를 잘라 넣었어요.","level":4,"category":"빈도 학습"},{"id":16051,"term":"bang","meaning":"쾅 치다; 세게 닫다","partOfSpeech":"v.","example":"Please don't bang the door when you leave.","exampleTranslation":"나갈 때 문을 쾅 닫지 마세요.","level":4,"category":"빈도 학습"},{"id":16052,"term":"bare","meaning":"맨~의; 벌거벗은","partOfSpeech":"adj.","example":"He walked across the hot sand with bare feet.","exampleTranslation":"그는 맨발로 뜨거운 모래 위를 걸었어요.","level":4,"category":"빈도 학습"},{"id":16053,"term":"bark","meaning":"(개가) 짖다","partOfSpeech":"v.","example":"The dog began to bark loudly at the mail carrier.","exampleTranslation":"그 개는 우편배달부를 향해 큰 소리로 짖기 시작했어요.","level":4,"category":"빈도 학습"},{"id":16054,"term":"basket","meaning":"바구니","partOfSpeech":"n.","example":"She put the fresh vegetables in a woven basket.","exampleTranslation":"그녀는 신선한 채소를 엮어 만든 바구니에 담았어요.","level":4,"category":"빈도 학습"},{"id":16055,"term":"bat","meaning":"(야구 방망이로) 치다","partOfSpeech":"v.","example":"He likes to bat left-handed during practice.","exampleTranslation":"그는 연습 중에 왼손으로 치는 것을 좋아해요.","level":4,"category":"빈도 학습"},{"id":16056,"term":"battery","meaning":"배터리; 건전지","partOfSpeech":"n.","example":"My phone battery died before I could call you.","exampleTranslation":"당신에게 전화하기도 전에 제 휴대폰 배터리가 다 됐어요.","level":4,"category":"빈도 학습"},{"id":16057,"term":"bay","meaning":"만(灣)","partOfSpeech":"n.","example":"The fishing boats returned to the bay before the storm hit.","exampleTranslation":"폭풍이 닥치기 전에 어선들이 만으로 돌아왔어요.","level":4,"category":"빈도 학습"},{"id":16058,"term":"bean","meaning":"콩","partOfSpeech":"n.","example":"We made a fresh salad with bean sprouts and lettuce.","exampleTranslation":"우리는 콩나물과 양상추로 신선한 샐러드를 만들었어요.","level":4,"category":"빈도 학습"},{"id":16059,"term":"bee","meaning":"벌","partOfSpeech":"n.","example":"A bee landed on the bright yellow flower.","exampleTranslation":"벌 한 마리가 밝은 노란 꽃에 앉았어요.","level":4,"category":"빈도 학습"},{"id":16060,"term":"beef","meaning":"소고기","partOfSpeech":"n.","example":"They grilled beef and vegetables for dinner.","exampleTranslation":"그들은 저녁으로 소고기와 채소를 구웠어요.","level":4,"category":"빈도 학습"},{"id":16061,"term":"beg","meaning":"간청하다; 구걸하다","partOfSpeech":"v.","example":"I beg you to reconsider your decision.","exampleTranslation":"당신의 결정을 재고해 주시기를 간청해요.","level":4,"category":"빈도 학습"},{"id":16062,"term":"biscuit","meaning":"비스킷","partOfSpeech":"n.","example":"She served a warm biscuit with butter and honey.","exampleTranslation":"그녀는 버터와 꿀을 곁들인 따뜻한 비스킷 하나를 대접했어요.","level":4,"category":"빈도 학습"},{"id":16063,"term":"blank","meaning":"빈; 백지의","partOfSpeech":"adj.","example":"Please leave this field blank if it doesn't apply to you.","exampleTranslation":"해당되지 않으면 이 항목을 빈칸으로 남겨두세요.","level":4,"category":"빈도 학습"},{"id":16064,"term":"million","meaning":"백만","partOfSpeech":"n.","example":"One million equals a one followed by six zeros.","exampleTranslation":"백만은 1 뒤에 0이 여섯 개 오는 수와 같아요.","level":4,"category":"빈도 학습"},{"id":16065,"term":"mine","meaning":"나의 것","partOfSpeech":"pron.","example":"This umbrella is mine, not yours.","exampleTranslation":"이 우산은 제 것이지, 당신 것이 아니에요.","level":4,"category":"빈도 학습"},{"id":16066,"term":"mister","meaning":"~씨; 남자를 부르는 말","partOfSpeech":"n.","example":"Excuse me, mister, could you help me carry this box?","exampleTranslation":"실례합니다, 아저씨, 이 상자 옮기는 것 좀 도와주시겠어요?","level":4,"category":"빈도 학습"},{"id":16067,"term":"monday","meaning":"월요일","partOfSpeech":"n.","example":"The office reopens on Monday morning.","exampleTranslation":"사무실은 월요일 아침에 다시 문을 열어요.","level":4,"category":"빈도 학습"},{"id":16068,"term":"mrs","meaning":"~씨 (기혼 여성 호칭)","partOfSpeech":"n.","example":"Mrs. Johnson teaches our English class.","exampleTranslation":"존슨 부인께서 우리 영어 수업을 가르치세요.","level":4,"category":"빈도 학습"},{"id":16069,"term":"much","meaning":"많은; 많이","partOfSpeech":"adj.","example":"Please try to save as much money as possible this month.","exampleTranslation":"이번 달에는 가능한 한 돈을 많이 저축하려고 노력해 보세요.","level":4,"category":"빈도 학습"},{"id":16070,"term":"mum","meaning":"엄마 (영국식)","partOfSpeech":"n.","example":"My mum always packs a healthy lunch for me.","exampleTranslation":"저희 엄마는 항상 저를 위해 건강한 도시락을 싸주세요.","level":4,"category":"빈도 학습"},{"id":16071,"term":"academy","meaning":"학원; 아카데미","partOfSpeech":"n.","example":"She enrolled in a dance academy last spring.","exampleTranslation":"그녀는 지난봄에 무용 학원에 등록했어요.","level":5,"category":"빈도 학습"},{"id":16072,"term":"accelerate","meaning":"가속하다; 속도를 높이다","partOfSpeech":"v.","example":"The driver had to accelerate quickly to merge onto the highway.","exampleTranslation":"운전자는 고속도로에 합류하기 위해 빠르게 가속해야 했어요.","level":5,"category":"빈도 학습"},{"id":16073,"term":"accountable","meaning":"책임이 있는","partOfSpeech":"adj.","example":"Managers should be held accountable for their team's mistakes.","exampleTranslation":"관리자는 팀의 실수에 대해 책임을 져야 해요.","level":5,"category":"빈도 학습"},{"id":16074,"term":"accumulate","meaning":"축적하다; 쌓이다","partOfSpeech":"v.","example":"Dust tends to accumulate quickly on bookshelves.","exampleTranslation":"먼지는 책장 위에 빠르게 쌓이는 경향이 있어요.","level":5,"category":"빈도 학습"},{"id":16075,"term":"ache","meaning":"아프다; 쑤시다","partOfSpeech":"v.","example":"My legs ache after running the marathon.","exampleTranslation":"마라톤을 뛰고 나니 다리가 쑤셔요.","level":5,"category":"빈도 학습"},{"id":16076,"term":"blanket","meaning":"뒤덮다; 완전히 덮다","partOfSpeech":"v.","example":"Thick snow is expected to blanket the entire town by morning.","exampleTranslation":"짙은 눈이 아침까지 온 마을을 뒤덮을 것으로 예상돼요.","level":5,"category":"빈도 학습"},{"id":16077,"term":"bleed","meaning":"피를 흘리다; 출혈하다","partOfSpeech":"v.","example":"The cut on his finger began to bleed.","exampleTranslation":"그의 손가락에 난 상처에서 피가 나기 시작했어요.","level":5,"category":"빈도 학습"},{"id":16078,"term":"blonde","meaning":"금발의","partOfSpeech":"adj.","example":"Her blonde hair shone brightly in the sunlight.","exampleTranslation":"그녀의 금발 머리가 햇빛 속에서 밝게 빛났어요.","level":5,"category":"빈도 학습"},{"id":16079,"term":"bloom","meaning":"꽃을 피우다","partOfSpeech":"v.","example":"The roses in the garden bloom every spring.","exampleTranslation":"정원의 장미는 매년 봄에 꽃을 피워요.","level":5,"category":"빈도 학습"},{"id":16080,"term":"bounce","meaning":"튀다; 튀어 오르다","partOfSpeech":"v.","example":"The ball began to bounce down the stairs.","exampleTranslation":"그 공은 계단 아래로 튀기 시작했어요.","level":5,"category":"빈도 학습"},{"id":16081,"term":"bow","meaning":"(허리를 굽혀) 인사하다","partOfSpeech":"v.","example":"The performers bow to the audience at the end of the show.","exampleTranslation":"공연자들은 공연이 끝날 때 관객에게 고개 숙여 인사해요.","level":5,"category":"빈도 학습"},{"id":16082,"term":"brake","meaning":"브레이크를 밟다; 제동을 걸다","partOfSpeech":"v.","example":"The driver had to brake suddenly to avoid the dog.","exampleTranslation":"운전자는 개를 피하기 위해 갑자기 브레이크를 밟아야 했어요.","level":5,"category":"빈도 학습"},{"id":16083,"term":"brave","meaning":"용감한","partOfSpeech":"adj.","example":"It was brave of her to speak up in front of everyone.","exampleTranslation":"모두 앞에서 목소리를 낸 것은 그녀에게 용감한 행동이었어요.","level":5,"category":"빈도 학습"},{"id":16084,"term":"brick","meaning":"벽돌","partOfSpeech":"n.","example":"The old house was built entirely of red brick.","exampleTranslation":"그 오래된 집은 전체가 붉은 벽돌로 지어졌어요.","level":5,"category":"빈도 학습"},{"id":16085,"term":"buck","meaning":"(말이) 날뛰다; 반항하다","partOfSpeech":"v.","example":"The wild horse began to buck as soon as someone tried to ride it.","exampleTranslation":"누군가 올라타려 하자마자 그 야생마는 날뛰기 시작했어요.","level":5,"category":"빈도 학습"},{"id":16086,"term":"bucket","meaning":"양동이","partOfSpeech":"n.","example":"He filled the bucket with water to wash the car.","exampleTranslation":"그는 세차하려고 양동이에 물을 채웠어요.","level":5,"category":"빈도 학습"},{"id":16087,"term":"bump","meaning":"부딪히다; 우연히 마주치다","partOfSpeech":"v.","example":"I often bump into my old friend at the mall.","exampleTranslation":"저는 그 쇼핑몰에서 종종 옛 친구와 우연히 마주쳐요.","level":5,"category":"빈도 학습"},{"id":16088,"term":"butter","meaning":"버터","partOfSpeech":"n.","example":"She spread butter on the warm toast.","exampleTranslation":"그녀는 따뜻한 토스트에 버터를 발랐어요.","level":5,"category":"빈도 학습"},{"id":16089,"term":"cage","meaning":"새장; 우리","partOfSpeech":"n.","example":"The parrot was kept in a large cage by the window.","exampleTranslation":"그 앵무새는 창가의 큰 새장에 있었어요.","level":5,"category":"빈도 학습"},{"id":16090,"term":"myself","meaning":"나 자신","partOfSpeech":"pron.","example":"I taught myself how to play the guitar.","exampleTranslation":"저는 기타 치는 법을 독학했어요.","level":5,"category":"빈도 학습"},{"id":16091,"term":"naughty","meaning":"장난꾸러기인; 버릇없는","partOfSpeech":"adj.","example":"The naughty puppy chewed up my favorite shoes.","exampleTranslation":"그 장난꾸러기 강아지가 제가 가장 아끼는 신발을 물어뜯었어요.","level":5,"category":"빈도 학습"},{"id":16092,"term":"neat","meaning":"깔끔한; 정돈된","partOfSpeech":"adj.","example":"He always keeps his desk neat and organized.","exampleTranslation":"그는 항상 책상을 깔끔하고 정돈되게 유지해요.","level":5,"category":"빈도 학습"},{"id":16093,"term":"never","meaning":"결코 ~않다","partOfSpeech":"adv.","example":"Never mind, I'll figure it out myself.","exampleTranslation":"신경 쓰지 마세요, 제가 알아서 할게요.","level":5,"category":"빈도 학습"},{"id":16094,"term":"nine","meaning":"아홉; 9","partOfSpeech":"adj.","example":"A cat is said to have nine lives.","exampleTranslation":"고양이는 목숨이 아홉 개라고 해요.","level":5,"category":"빈도 학습"},{"id":16095,"term":"acre","meaning":"에이커 (면적 단위)","partOfSpeech":"n.","example":"The farm covers more than one acre of land.","exampleTranslation":"그 농장은 1에이커가 넘는 땅을 차지하고 있어요.","level":6,"category":"빈도 학습"},{"id":16096,"term":"addict","meaning":"중독자","partOfSpeech":"n.","example":"He became a video game addict during the summer break.","exampleTranslation":"그는 여름 방학 동안 비디오 게임 중독자가 되었어요.","level":6,"category":"빈도 학습"},{"id":16097,"term":"administrative","meaning":"행정의; 관리의","partOfSpeech":"adj.","example":"She handles all the administrative tasks in the office.","exampleTranslation":"그녀는 사무실의 모든 행정 업무를 처리해요.","level":6,"category":"빈도 학습"},{"id":16098,"term":"administrator","meaning":"관리자; 행정관","partOfSpeech":"n.","example":"The school hired a new administrator to manage enrollment.","exampleTranslation":"그 학교는 입학 관리를 위해 새 관리자를 채용했어요.","level":6,"category":"빈도 학습"},{"id":16099,"term":"admission","meaning":"입장; 입학","partOfSpeech":"n.","example":"Admission to the museum is free on Sundays.","exampleTranslation":"일요일에는 박물관 입장이 무료예요.","level":6,"category":"빈도 학습"},{"id":16100,"term":"adolescent","meaning":"청소년의; 사춘기의","partOfSpeech":"adj.","example":"Adolescent behavior can be unpredictable and full of change.","exampleTranslation":"청소년기의 행동은 예측하기 어렵고 변화가 많을 수 있어요.","level":6,"category":"빈도 학습"},{"id":16101,"term":"affection","meaning":"애정","partOfSpeech":"n.","example":"The dog showed great affection by wagging its tail.","exampleTranslation":"그 개는 꼬리를 흔들며 큰 애정을 보였어요.","level":6,"category":"빈도 학습"},{"id":16102,"term":"canoe","meaning":"카누를 타다","partOfSpeech":"v.","example":"They canoe across the lake every summer morning.","exampleTranslation":"그들은 매년 여름 아침마다 호수를 가로질러 카누를 타요.","level":6,"category":"빈도 학습"},{"id":16103,"term":"cape","meaning":"망토; 곶(岬)","partOfSpeech":"n.","example":"The superhero's red cape fluttered in the wind.","exampleTranslation":"그 슈퍼히어로의 빨간 망토가 바람에 펄럭였어요.","level":6,"category":"빈도 학습"},{"id":16104,"term":"captain","meaning":"(팀을) 이끌다; 주장을 맡다","partOfSpeech":"v.","example":"She will captain the national team at the next tournament.","exampleTranslation":"그녀는 다음 대회에서 국가대표팀 주장을 맡을 거예요.","level":6,"category":"빈도 학습"},{"id":16105,"term":"carrot","meaning":"당근","partOfSpeech":"n.","example":"She chopped a carrot for the vegetable soup.","exampleTranslation":"그녀는 채소 수프를 위해 당근을 썰었어요.","level":6,"category":"빈도 학습"},{"id":16106,"term":"cart","meaning":"실어 나르다","partOfSpeech":"v.","example":"Workers had to cart the heavy boxes up three flights of stairs.","exampleTranslation":"작업자들은 무거운 상자들을 계단 세 층 위로 실어 날라야 했어요.","level":6,"category":"빈도 학습"},{"id":16107,"term":"casual","meaning":"격식 없는; 평상시의","partOfSpeech":"adj.","example":"The office allows casual clothing on Fridays.","exampleTranslation":"그 사무실은 금요일에 평상복을 허용해요.","level":6,"category":"빈도 학습"},{"id":16108,"term":"ceiling","meaning":"천장","partOfSpeech":"n.","example":"A large fan hung from the ceiling of the room.","exampleTranslation":"그 방의 천장에는 큰 선풍기가 매달려 있었어요.","level":6,"category":"빈도 학습"},{"id":16109,"term":"centimeter","meaning":"센티미터","partOfSpeech":"n.","example":"The board is one centimeter thick.","exampleTranslation":"그 판자는 두께가 1센티미터예요.","level":6,"category":"빈도 학습"},{"id":16110,"term":"cheat","meaning":"속이다; 부정행위를 하다","partOfSpeech":"v.","example":"He was caught trying to cheat on the exam.","exampleTranslation":"그는 시험에서 부정행위를 하려다 걸렸어요.","level":6,"category":"빈도 학습"},{"id":16111,"term":"cheer","meaning":"환호하다; 응원하다","partOfSpeech":"v.","example":"The fans began to cheer loudly as the team scored.","exampleTranslation":"팀이 득점하자 팬들은 큰 소리로 환호하기 시작했어요.","level":6,"category":"빈도 학습"},{"id":16112,"term":"chew","meaning":"씹다","partOfSpeech":"v.","example":"You should chew your food slowly before swallowing.","exampleTranslation":"삼키기 전에 음식을 천천히 씹어야 해요.","level":6,"category":"빈도 학습"},{"id":16113,"term":"chop","meaning":"잘게 썰다; 다지다","partOfSpeech":"v.","example":"Please chop the onions finely for the sauce.","exampleTranslation":"소스를 위해 양파를 잘게 썰어 주세요.","level":6,"category":"빈도 학습"},{"id":16114,"term":"clever","meaning":"영리한; 똑똑한","partOfSpeech":"adj.","example":"That was a clever solution to a tricky problem.","exampleTranslation":"그건 까다로운 문제에 대한 영리한 해결책이었어요.","level":6,"category":"빈도 학습"},{"id":16115,"term":"one","meaning":"하나; 서로 (one another)","partOfSpeech":"pron.","example":"The team members always help one another during difficult projects.","exampleTranslation":"팀원들은 어려운 프로젝트 중에 항상 서로 도와요.","level":6,"category":"빈도 학습"},{"id":16116,"term":"other","meaning":"다른; 그 밖의","partOfSpeech":"adj.","example":"On the other hand, taking the train might be cheaper.","exampleTranslation":"반면에, 기차를 타는 것이 더 저렴할 수도 있어요.","level":6,"category":"빈도 학습"},{"id":16117,"term":"ought","meaning":"~해야 한다","partOfSpeech":"v.","example":"You ought to apologize for what you said.","exampleTranslation":"당신이 한 말에 대해 사과해야 해요.","level":6,"category":"빈도 학습"},{"id":16118,"term":"pardon","meaning":"용서하다; 양해하다","partOfSpeech":"v.","example":"Please pardon my late reply to your email.","exampleTranslation":"이메일 답장이 늦은 것을 양해해 주세요.","level":6,"category":"빈도 학습"},{"id":16119,"term":"penny","meaning":"페니 (동전)","partOfSpeech":"n.","example":"He found a shiny penny on the sidewalk.","exampleTranslation":"그는 보도에서 반짝이는 1페니 동전을 발견했어요.","level":6,"category":"빈도 학습"},{"id":16120,"term":"prince","meaning":"왕자","partOfSpeech":"n.","example":"The young prince will inherit the throne someday.","exampleTranslation":"그 젊은 왕자는 언젠가 왕위를 물려받을 거예요.","level":6,"category":"빈도 학습"},{"id":16121,"term":"affirm","meaning":"확언하다; 단언하다","partOfSpeech":"v.","example":"The witness will affirm that she saw the accident happen.","exampleTranslation":"그 목격자는 사고가 일어나는 것을 봤다고 확언할 거예요.","level":7,"category":"빈도 학습"},{"id":16122,"term":"agriculture","meaning":"농업","partOfSpeech":"n.","example":"Agriculture remains the main industry in this region.","exampleTranslation":"농업은 이 지역의 주요 산업으로 남아 있어요.","level":7,"category":"빈도 학습"},{"id":16123,"term":"alien","meaning":"외계의; 낯선","partOfSpeech":"adj.","example":"The idea of working from home felt alien to him at first.","exampleTranslation":"처음에 그에게 재택근무라는 개념은 낯설게 느껴졌어요.","level":7,"category":"빈도 학습"},{"id":16124,"term":"alliance","meaning":"동맹","partOfSpeech":"n.","example":"The two countries formed an alliance to promote trade.","exampleTranslation":"두 나라는 무역을 촉진하기 위해 동맹을 맺었어요.","level":7,"category":"빈도 학습"},{"id":16125,"term":"amend","meaning":"개정하다; 수정하다","partOfSpeech":"v.","example":"The committee voted to amend the outdated policy.","exampleTranslation":"위원회는 낡은 정책을 개정하기로 투표했어요.","level":7,"category":"빈도 학습"},{"id":16126,"term":"approximate","meaning":"대략의; 근사한","partOfSpeech":"adj.","example":"Can you give me an approximate time for the delivery?","exampleTranslation":"배송의 대략적인 시간을 알려주실 수 있나요?","level":7,"category":"빈도 학습"},{"id":16127,"term":"cliff","meaning":"절벽","partOfSpeech":"n.","example":"The house stood dangerously close to the edge of the cliff.","exampleTranslation":"그 집은 절벽 가장자리에 위험할 정도로 가까이 서 있었어요.","level":7,"category":"빈도 학습"},{"id":16128,"term":"clip","meaning":"자르다; 깎다","partOfSpeech":"v.","example":"She used scissors to clip the coupon from the newspaper.","exampleTranslation":"그녀는 가위로 신문에서 쿠폰을 오려냈어요.","level":7,"category":"빈도 학습"},{"id":16129,"term":"cloth","meaning":"천; 옷감","partOfSpeech":"n.","example":"He wiped the table with a damp cloth.","exampleTranslation":"그는 축축한 천으로 탁자를 닦았어요.","level":7,"category":"빈도 학습"},{"id":16130,"term":"clue","meaning":"(clue in) 알려주다; 정보를 주다","partOfSpeech":"v.","example":"Could you clue me in on what happened at the meeting?","exampleTranslation":"회의에서 무슨 일이 있었는지 저에게 알려주시겠어요?","level":7,"category":"빈도 학습"},{"id":16131,"term":"commerce","meaning":"상업; 통상","partOfSpeech":"n.","example":"The internet has completely transformed global commerce.","exampleTranslation":"인터넷은 세계 상업을 완전히 변화시켰어요.","level":7,"category":"빈도 학습"},{"id":16132,"term":"conscious","meaning":"의식이 있는; 자각하는","partOfSpeech":"adj.","example":"The patient remained conscious throughout the entire procedure.","exampleTranslation":"그 환자는 시술 내내 의식이 있는 상태였어요.","level":7,"category":"빈도 학습"},{"id":16133,"term":"cop","meaning":"경찰관","partOfSpeech":"n.","example":"A cop signaled the driver to pull over.","exampleTranslation":"경찰관이 운전자에게 차를 세우라고 신호했어요.","level":7,"category":"빈도 학습"},{"id":16134,"term":"cottage","meaning":"오두막집; 시골집","partOfSpeech":"n.","example":"They spent the weekend at a cozy cottage by the lake.","exampleTranslation":"그들은 호숫가의 아늑한 오두막집에서 주말을 보냈어요.","level":7,"category":"빈도 학습"},{"id":16135,"term":"cotton","meaning":"면; 목화","partOfSpeech":"n.","example":"This shirt is made of one hundred percent cotton.","exampleTranslation":"이 셔츠는 100퍼센트 면으로 만들어졌어요.","level":7,"category":"빈도 학습"},{"id":16136,"term":"crawl","meaning":"기어가다","partOfSpeech":"v.","example":"The baby began to crawl across the living room floor.","exampleTranslation":"아기가 거실 바닥을 가로질러 기어가기 시작했어요.","level":7,"category":"빈도 학습"},{"id":16137,"term":"creep","meaning":"살금살금 걷다; 기다","partOfSpeech":"v.","example":"The cat began to creep slowly toward the sleeping bird.","exampleTranslation":"그 고양이는 잠든 새를 향해 천천히 살금살금 다가가기 시작했어요.","level":7,"category":"빈도 학습"},{"id":16138,"term":"crown","meaning":"왕관을 씌우다; 즉위시키다","partOfSpeech":"v.","example":"They will crown the new king in a grand ceremony next month.","exampleTranslation":"그들은 다음 달 성대한 의식에서 새 왕에게 왕관을 씌울 거예요.","level":7,"category":"빈도 학습"},{"id":16139,"term":"cruel","meaning":"잔인한","partOfSpeech":"adj.","example":"It was cruel of him to laugh at her mistake.","exampleTranslation":"그녀의 실수를 비웃다니 그는 잔인했어요.","level":7,"category":"빈도 학습"},{"id":16140,"term":"queen","meaning":"여왕","partOfSpeech":"n.","example":"The queen greeted the crowd from the palace balcony.","exampleTranslation":"여왕은 궁전 발코니에서 군중에게 인사했어요.","level":7,"category":"빈도 학습"},{"id":16141,"term":"rabbit","meaning":"토끼","partOfSpeech":"n.","example":"A white rabbit hopped across the garden.","exampleTranslation":"하얀 토끼 한 마리가 정원을 가로질러 뛰어갔어요.","level":7,"category":"빈도 학습"},{"id":16142,"term":"rubbish","meaning":"혹평하다; 헐뜯다","partOfSpeech":"v.","example":"Critics always rubbish his films for their weak plots.","exampleTranslation":"평론가들은 그의 영화들을 약한 줄거리 때문에 항상 혹평해요.","level":7,"category":"빈도 학습"},{"id":16143,"term":"saturday","meaning":"토요일","partOfSpeech":"n.","example":"We are planning a picnic this Saturday.","exampleTranslation":"우리는 이번 토요일에 소풍을 계획하고 있어요.","level":7,"category":"빈도 학습"},{"id":16144,"term":"seven","meaning":"일곱; 7","partOfSpeech":"adj.","example":"There are seven days in a week.","exampleTranslation":"한 주에는 요일이 일곱 개 있어요.","level":7,"category":"빈도 학습"},{"id":16145,"term":"archaeology","meaning":"고고학","partOfSpeech":"n.","example":"She studied archaeology to learn about ancient civilizations.","exampleTranslation":"그녀는 고대 문명에 대해 배우기 위해 고고학을 공부했어요.","level":8,"category":"빈도 학습"},{"id":16146,"term":"architect","meaning":"설계하다; 구상하다","partOfSpeech":"v.","example":"The engineer wants to architect a scalable solution for the new app.","exampleTranslation":"그 엔지니어는 새 앱을 위한 확장 가능한 해결책을 설계하고 싶어해요.","level":8,"category":"빈도 학습"},{"id":16147,"term":"aspect","meaning":"측면; 양상","partOfSpeech":"n.","example":"Communication is an important aspect of teamwork.","exampleTranslation":"의사소통은 팀워크의 중요한 측면이에요.","level":8,"category":"빈도 학습"},{"id":16148,"term":"assault","meaning":"공격하다; 폭행하다","partOfSpeech":"v.","example":"Security staff are trained to step in if someone tries to assault a customer.","exampleTranslation":"보안 직원들은 누군가 고객을 폭행하려 하면 개입하도록 훈련받아요.","level":8,"category":"빈도 학습"},{"id":16149,"term":"assembly","meaning":"집회; 조립","partOfSpeech":"n.","example":"The whole school gathered for the morning assembly.","exampleTranslation":"전교생이 아침 조회를 위해 모였어요.","level":8,"category":"빈도 학습"},{"id":16150,"term":"assert","meaning":"주장하다; (권리 등을) 내세우다","partOfSpeech":"v.","example":"She decided to assert her opinion clearly during the debate.","exampleTranslation":"그녀는 토론 중에 자신의 의견을 분명하게 주장하기로 했습니다.","level":8,"category":"빈도 학습"},{"id":16151,"term":"atom","meaning":"원자","partOfSpeech":"n.","example":"Every atom is made up of a nucleus and surrounding electrons.","exampleTranslation":"모든 원자는 핵과 그 주위를 도는 전자로 이루어져 있습니다.","level":8,"category":"빈도 학습"},{"id":16152,"term":"audit","meaning":"감사하다; 회계를 검사하다","partOfSpeech":"v.","example":"An outside firm will audit the company's accounts next month.","exampleTranslation":"외부 업체가 다음 달에 그 회사의 회계를 감사할 것입니다.","level":8,"category":"빈도 학습"},{"id":16153,"term":"authority","meaning":"권한; 권위","partOfSpeech":"n.","example":"The manager has the authority to approve overtime pay.","exampleTranslation":"그 관리자는 초과 근무 수당을 승인할 권한이 있습니다.","level":8,"category":"빈도 학습"},{"id":16154,"term":"authorize","meaning":"승인하다; 권한을 부여하다","partOfSpeech":"v.","example":"Only the director can authorize this kind of expense.","exampleTranslation":"이런 종류의 지출은 이사만이 승인할 수 있습니다.","level":8,"category":"빈도 학습"},{"id":16155,"term":"bacterium","meaning":"박테리아 한 개체; 세균","partOfSpeech":"n.","example":"Under the microscope, a single bacterium looked like a tiny rod.","exampleTranslation":"현미경 아래에서 박테리아 한 개체는 작은 막대처럼 보였습니다.","level":8,"category":"빈도 학습"},{"id":16156,"term":"beam","meaning":"환하게 웃다; 빛을 비추다","partOfSpeech":"v.","example":"She always seems to beam with pride whenever her daughter succeeds.","exampleTranslation":"그녀는 딸이 성공할 때마다 항상 자랑스러움에 환하게 웃는 것 같습니다.","level":8,"category":"빈도 학습"},{"id":16157,"term":"bench","meaning":"벤치에 앉히다; 출전시키지 않다","partOfSpeech":"v.","example":"The coach chose to bench the tired striker for the second half.","exampleTranslation":"감독은 지친 공격수를 후반전에 벤치에 앉히기로 했습니다.","level":8,"category":"빈도 학습"},{"id":16158,"term":"bible","meaning":"성경; (특정 분야의) 지침서","partOfSpeech":"n.","example":"This cookbook has become the bible for home bakers everywhere.","exampleTranslation":"이 요리책은 어디서나 홈베이커들의 지침서가 되었습니다.","level":8,"category":"빈도 학습"},{"id":16159,"term":"cure","meaning":"치료하다; 고치다","partOfSpeech":"v.","example":"Doctors are working hard to cure the rare disease.","exampleTranslation":"의사들은 그 희귀병을 치료하기 위해 열심히 노력하고 있습니다.","level":8,"category":"빈도 학습"},{"id":16160,"term":"curl","meaning":"곱슬거리게 하다; 감다","partOfSpeech":"v.","example":"She likes to curl her hair before going out on weekends.","exampleTranslation":"그녀는 주말에 외출하기 전에 머리를 곱슬거리게 만드는 것을 좋아합니다.","level":8,"category":"빈도 학습"},{"id":16161,"term":"dawn","meaning":"(날이) 밝다; 동트다","partOfSpeech":"v.","example":"In summer, the day begins to dawn around five in the morning.","exampleTranslation":"여름에는 다섯 시쯤 날이 밝아오기 시작합니다.","level":8,"category":"빈도 학습"},{"id":16162,"term":"december","meaning":"12월","partOfSpeech":"n.","example":"The whole family gathers together every December for the holidays.","exampleTranslation":"온 가족이 매년 12월마다 명절을 위해 모입니다.","level":8,"category":"빈도 학습"},{"id":16163,"term":"decent","meaning":"괜찮은; 품위 있는","partOfSpeech":"adj.","example":"He earns a decent salary at his new job downtown.","exampleTranslation":"그는 시내에 있는 새 직장에서 괜찮은 급여를 받습니다.","level":8,"category":"빈도 학습"},{"id":16164,"term":"deck","meaning":"갑판; 데크","partOfSpeech":"n.","example":"The passengers gathered on the upper deck to watch the sunset.","exampleTranslation":"승객들은 일몰을 보기 위해 상갑판에 모였습니다.","level":8,"category":"빈도 학습"},{"id":16165,"term":"decorate","meaning":"장식하다; 꾸미다","partOfSpeech":"v.","example":"They decorate the tree every December before Christmas.","exampleTranslation":"그들은 크리스마스 전 12월마다 트리를 장식합니다.","level":8,"category":"빈도 학습"},{"id":16166,"term":"desperate","meaning":"절박한; 필사적인","partOfSpeech":"adj.","example":"She was desperate to find a job before the rent was due.","exampleTranslation":"그녀는 집세 내기 전에 절박하게 일자리를 구하고 있었습니다.","level":8,"category":"빈도 학습"},{"id":16167,"term":"dine","meaning":"식사하다; 정찬을 들다","partOfSpeech":"v.","example":"They plan to dine at a fancy restaurant tonight.","exampleTranslation":"그들은 오늘 밤 고급 레스토랑에서 식사할 계획입니다.","level":8,"category":"빈도 학습"},{"id":16168,"term":"disgust","meaning":"역겹게 하다; 혐오감을 주다","partOfSpeech":"v.","example":"His constant lying continues to disgust his closest friends.","exampleTranslation":"그의 끊임없는 거짓말은 가장 가까운 친구들에게도 계속 역겨움을 줍니다.","level":8,"category":"빈도 학습"},{"id":16169,"term":"dive","meaning":"뛰어들다; 잠수하다","partOfSpeech":"v.","example":"Every summer, tourists dive off that cliff into the clear water.","exampleTranslation":"매년 여름 관광객들은 그 절벽에서 맑은 물속으로 뛰어듭니다.","level":8,"category":"빈도 학습"},{"id":16170,"term":"doll","meaning":"인형","partOfSpeech":"n.","example":"The little girl carried her favorite doll everywhere she went.","exampleTranslation":"그 어린 소녀는 어디를 가든 가장 좋아하는 인형을 가지고 다녔습니다.","level":8,"category":"빈도 학습"},{"id":16171,"term":"dragon","meaning":"용","partOfSpeech":"n.","example":"In the story, a fierce dragon guarded the ancient castle.","exampleTranslation":"이야기 속에서 사나운 용이 고대 성을 지키고 있었습니다.","level":8,"category":"빈도 학습"},{"id":16172,"term":"shy","meaning":"수줍은; 낯을 가리는","partOfSpeech":"adj.","example":"He was too shy to speak in front of the whole class.","exampleTranslation":"그는 너무 수줍어서 반 전체 앞에서 말하지 못했습니다.","level":8,"category":"빈도 학습"},{"id":16173,"term":"since","meaning":"~한 이후로; ~때문에","partOfSpeech":"conj.","example":"I haven't seen her since we graduated from high school together.","exampleTranslation":"우리가 함께 고등학교를 졸업한 이후로 나는 그녀를 보지 못했습니다.","level":8,"category":"빈도 학습"},{"id":16174,"term":"six","meaning":"여섯의; 6의","partOfSpeech":"adj.","example":"The meeting is scheduled to start at six o'clock sharp.","exampleTranslation":"회의는 정확히 6시에 시작할 예정입니다.","level":8,"category":"빈도 학습"},{"id":16175,"term":"sunday","meaning":"일요일","partOfSpeech":"n.","example":"We usually visit my grandparents every Sunday afternoon.","exampleTranslation":"우리는 보통 일요일 오후마다 조부모님을 뵈러 갑니다.","level":8,"category":"빈도 학습"},{"id":16176,"term":"ten","meaning":"열의; 10의","partOfSpeech":"adj.","example":"She has been studying English for ten years now.","exampleTranslation":"그녀는 지금까지 10년 동안 영어를 공부해 왔습니다.","level":8,"category":"빈도 학습"},{"id":16177,"term":"bishop","meaning":"주교","partOfSpeech":"n.","example":"The bishop gave a moving speech at the cathedral service.","exampleTranslation":"그 주교는 대성당 예배에서 감동적인 연설을 했습니다.","level":9,"category":"빈도 학습"},{"id":16178,"term":"blast","meaning":"크게 틀다; 폭파하다","partOfSpeech":"v.","example":"He likes to blast music while cleaning the house.","exampleTranslation":"그는 집을 청소할 때 음악을 크게 트는 것을 좋아합니다.","level":9,"category":"빈도 학습"},{"id":16179,"term":"blend","meaning":"섞다; 혼합하다","partOfSpeech":"v.","example":"Blend the flour and sugar together before adding the eggs.","exampleTranslation":"계란을 넣기 전에 밀가루와 설탕을 함께 섞으세요.","level":9,"category":"빈도 학습"},{"id":16180,"term":"bureau","meaning":"사무국; 서랍장","partOfSpeech":"n.","example":"She filed the complaint at the local government bureau downtown.","exampleTranslation":"그녀는 시내에 있는 지역 정부 사무국에 민원을 제출했습니다.","level":9,"category":"빈도 학습"},{"id":16181,"term":"cabinet","meaning":"내각; 캐비닛","partOfSpeech":"n.","example":"The president will meet with the cabinet to discuss the new policy.","exampleTranslation":"대통령은 새 정책을 논의하기 위해 내각과 회의할 것입니다.","level":9,"category":"빈도 학습"},{"id":16182,"term":"carve","meaning":"조각하다; 새기다","partOfSpeech":"v.","example":"The artist used a sharp knife to carve the wooden statue.","exampleTranslation":"그 예술가는 날카로운 칼을 사용해 나무 조각상을 새겼습니다.","level":9,"category":"빈도 학습"},{"id":16184,"term":"catholic","meaning":"가톨릭의; (드물게) 포괄적인","partOfSpeech":"adj.","example":"She grew up in a strict Catholic family in rural Ireland.","exampleTranslation":"그녀는 아일랜드 시골의 엄격한 가톨릭 가정에서 자랐습니다.","level":9,"category":"빈도 학습"},{"id":16185,"term":"cattle","meaning":"소, 축우","partOfSpeech":"n.","example":"The farmer keeps about two hundred cattle on his land.","exampleTranslation":"그 농부는 자신의 땅에서 약 200마리의 소를 기릅니다.","level":9,"category":"빈도 학습"},{"id":16186,"term":"cease","meaning":"중단하다; 그치다","partOfSpeech":"v.","example":"The factory will cease operations by the end of the year.","exampleTranslation":"그 공장은 연말까지 운영을 중단할 것입니다.","level":9,"category":"빈도 학습"},{"id":16187,"term":"charter","meaning":"전세 내다; 특허를 주다","partOfSpeech":"v.","example":"The company decided to charter a private jet for the trip.","exampleTranslation":"그 회사는 출장을 위해 전용기를 전세 내기로 결정했습니다.","level":9,"category":"빈도 학습"},{"id":16188,"term":"chill","meaning":"차게 식히다; 진정하다","partOfSpeech":"v.","example":"Put the wine in the fridge to chill before dinner.","exampleTranslation":"저녁 식사 전에 와인을 차게 식히도록 냉장고에 넣으세요.","level":9,"category":"빈도 학습"},{"id":16189,"term":"circuit","meaning":"회로; 순환로","partOfSpeech":"n.","example":"The engineer traced the circuit to find the faulty connection.","exampleTranslation":"그 엔지니어는 결함이 있는 연결 부분을 찾기 위해 회로를 추적했습니다.","level":9,"category":"빈도 학습"},{"id":16190,"term":"circulate","meaning":"퍼지다; 순환하다","partOfSpeech":"v.","example":"Rumors began to circulate around the office quickly.","exampleTranslation":"소문이 사무실 안에 빠르게 퍼지기 시작했습니다.","level":9,"category":"빈도 학습"},{"id":16191,"term":"civilize","meaning":"문명화하다; 교화하다","partOfSpeech":"v.","example":"Education helps civilize society over many generations.","exampleTranslation":"교육은 여러 세대에 걸쳐 사회를 교화하는 데 도움을 줍니다.","level":9,"category":"빈도 학습"},{"id":16192,"term":"clarify","meaning":"명확히 하다; 분명히 말하다","partOfSpeech":"v.","example":"Could you clarify what you meant by that last comment?","exampleTranslation":"방금 하신 말씀이 무슨 뜻인지 명확히 해 주시겠어요?","level":9,"category":"빈도 학습"},{"id":16193,"term":"clinic","meaning":"진료소; 클리닉","partOfSpeech":"n.","example":"She works part-time at a small clinic near the station.","exampleTranslation":"그녀는 역 근처의 작은 진료소에서 시간제로 일합니다.","level":9,"category":"빈도 학습"},{"id":16194,"term":"drawer","meaning":"서랍","partOfSpeech":"n.","example":"He keeps all his important documents in the top drawer.","exampleTranslation":"그는 중요한 서류를 모두 맨 위 서랍에 보관합니다.","level":9,"category":"빈도 학습"},{"id":16195,"term":"drum","meaning":"손가락으로 두드리다; 북을 치다","partOfSpeech":"v.","example":"He began to drum his fingers on the table impatiently.","exampleTranslation":"그는 초조하게 손가락으로 탁자를 두드리기 시작했습니다.","level":9,"category":"빈도 학습"},{"id":16196,"term":"duck","meaning":"홱 수그리다; 머리를 숙이다","partOfSpeech":"v.","example":"Everyone had to duck quickly to avoid the low doorway.","exampleTranslation":"모두가 낮은 출입구를 피하려고 재빨리 몸을 숙여야 했습니다.","level":9,"category":"빈도 학습"},{"id":16197,"term":"dump","meaning":"버리다; 폐기하다","partOfSpeech":"v.","example":"Please don't dump your trash on the sidewalk.","exampleTranslation":"인도에 쓰레기를 버리지 말아 주세요.","level":9,"category":"빈도 학습"},{"id":16198,"term":"elder","meaning":"손위의; 연장자의","partOfSpeech":"adj.","example":"Her elder brother helps her with homework every evening.","exampleTranslation":"그녀의 손위 오빠는 매일 저녁 숙제를 도와줍니다.","level":9,"category":"빈도 학습"},{"id":16199,"term":"elephant","meaning":"코끼리","partOfSpeech":"n.","example":"The elephant at the zoo gently lifted the peanut with its trunk.","exampleTranslation":"동물원의 코끼리는 코로 땅콩을 부드럽게 집어 들었습니다.","level":9,"category":"빈도 학습"},{"id":16200,"term":"faint","meaning":"기절하다; 실신하다","partOfSpeech":"v.","example":"She began to faint after standing in the sun for too long.","exampleTranslation":"그녀는 햇볕 아래 너무 오래 서 있다가 기절하기 시작했습니다.","level":9,"category":"빈도 학습"},{"id":16201,"term":"fairy","meaning":"요정","partOfSpeech":"n.","example":"The children loved the story about a kind fairy in the forest.","exampleTranslation":"아이들은 숲속의 친절한 요정에 관한 이야기를 좋아했습니다.","level":9,"category":"빈도 학습"},{"id":16202,"term":"feather","meaning":"깃털","partOfSpeech":"n.","example":"A soft feather fell gently from the bird's wing.","exampleTranslation":"부드러운 깃털 하나가 새의 날개에서 살며시 떨어졌습니다.","level":9,"category":"빈도 학습"},{"id":16203,"term":"february","meaning":"2월","partOfSpeech":"n.","example":"The festival always takes place in early February.","exampleTranslation":"그 축제는 항상 2월 초에 열립니다.","level":9,"category":"빈도 학습"},{"id":16204,"term":"fetch","meaning":"가져오다; 데려오다","partOfSpeech":"v.","example":"Can you fetch some water from the kitchen, please?","exampleTranslation":"부엌에서 물 좀 가져다줄 수 있나요?","level":9,"category":"빈도 학습"},{"id":16205,"term":"themselves","meaning":"그들 자신; 스스로","partOfSpeech":"pron.","example":"The kids learned to solve the puzzle by themselves without any help.","exampleTranslation":"아이들은 아무 도움 없이 스스로 퍼즐을 푸는 법을 배웠습니다.","level":9,"category":"빈도 학습"},{"id":16206,"term":"thirteen","meaning":"열셋의; 13의","partOfSpeech":"adj.","example":"She turned thirteen years old last weekend.","exampleTranslation":"그녀는 지난 주말에 열세 살이 되었습니다.","level":9,"category":"빈도 학습"},{"id":16207,"term":"thirty","meaning":"서른의; 30의","partOfSpeech":"adj.","example":"He has worked at this company for thirty years.","exampleTranslation":"그는 이 회사에서 30년 동안 근무했습니다.","level":9,"category":"빈도 학습"},{"id":16208,"term":"though","meaning":"비록 ~이지만; 그렇지만","partOfSpeech":"conj.","example":"Even though it was raining heavily, they decided to go for a hike.","exampleTranslation":"비록 비가 세차게 내렸지만, 그들은 하이킹을 가기로 했습니다.","level":9,"category":"빈도 학습"},{"id":16209,"term":"coalition","meaning":"연합; 연립","partOfSpeech":"n.","example":"Several small parties formed a coalition to win the election.","exampleTranslation":"여러 소수 정당이 선거에서 이기기 위해 연합을 결성했습니다.","level":10,"category":"빈도 학습"},{"id":16210,"term":"coincide","meaning":"동시에 일어나다; 일치하다","partOfSpeech":"v.","example":"Her birthday happens to coincide with the national holiday this year.","exampleTranslation":"올해는 공교롭게도 그녀의 생일이 국경일과 겹칩니다.","level":10,"category":"빈도 학습"},{"id":16211,"term":"collaborate","meaning":"협력하다; 공동 작업하다","partOfSpeech":"v.","example":"The two studios agreed to collaborate on a new animated film.","exampleTranslation":"두 스튜디오는 새 애니메이션 영화에서 협력하기로 합의했습니다.","level":10,"category":"빈도 학습"},{"id":16212,"term":"colony","meaning":"식민지; 군집","partOfSpeech":"n.","example":"The ants built a large colony beneath the old oak tree.","exampleTranslation":"개미들은 오래된 참나무 아래에 커다란 군집을 만들었습니다.","level":10,"category":"빈도 학습"},{"id":16213,"term":"combat","meaning":"싸우다; 방지하다","partOfSpeech":"v.","example":"The city launched a new program to combat rising crime rates.","exampleTranslation":"그 도시는 증가하는 범죄율에 맞서 싸우기 위해 새 프로그램을 시작했습니다.","level":10,"category":"빈도 학습"},{"id":16214,"term":"communist","meaning":"공산주의의; 공산당원","partOfSpeech":"adj.","example":"The novel is set in a communist country during the Cold War.","exampleTranslation":"그 소설은 냉전 시대의 한 공산주의 국가를 배경으로 합니다.","level":10,"category":"빈도 학습"},{"id":16215,"term":"companion","meaning":"동반자; 친구","partOfSpeech":"n.","example":"The old dog has been her loyal companion for over a decade.","exampleTranslation":"그 늙은 개는 십 년 넘게 그녀의 충실한 동반자였습니다.","level":10,"category":"빈도 학습"},{"id":16216,"term":"compensate","meaning":"보상하다; 벌충하다","partOfSpeech":"v.","example":"The airline agreed to compensate passengers for the long delay.","exampleTranslation":"그 항공사는 긴 지연에 대해 승객들에게 보상하기로 합의했습니다.","level":10,"category":"빈도 학습"},{"id":16217,"term":"competent","meaning":"유능한; 능숙한","partOfSpeech":"adj.","example":"She is a highly competent lawyer with years of courtroom experience.","exampleTranslation":"그녀는 수년간의 법정 경험을 가진 매우 유능한 변호사입니다.","level":10,"category":"빈도 학습"},{"id":16218,"term":"conceive","meaning":"생각해내다; 상상하다","partOfSpeech":"v.","example":"It is hard to conceive how the ancient pyramids were built by hand.","exampleTranslation":"고대 피라미드가 어떻게 손으로 지어졌는지 상상하기 어렵습니다.","level":10,"category":"빈도 학습"},{"id":16219,"term":"condemn","meaning":"비난하다; 규탄하다","partOfSpeech":"v.","example":"World leaders quickly moved to condemn the violent attack.","exampleTranslation":"세계 지도자들은 신속하게 그 폭력적인 공격을 규탄했습니다.","level":10,"category":"빈도 학습"},{"id":16220,"term":"confer","meaning":"상의하다; 수여하다","partOfSpeech":"v.","example":"The lawyers need to confer privately before the trial continues.","exampleTranslation":"변호사들은 재판이 계속되기 전에 따로 상의해야 합니다.","level":10,"category":"빈도 학습"},{"id":16221,"term":"flame","meaning":"타오르다; 활활 타다","partOfSpeech":"v.","example":"Dry leaves and twigs began to flame as soon as they touched the campfire.","exampleTranslation":"마른 잎과 잔가지들은 캠프파이어에 닿자마자 타오르기 시작했습니다.","level":10,"category":"빈도 학습"},{"id":16222,"term":"flip","meaning":"휙 뒤집다; 젖히다","partOfSpeech":"v.","example":"He likes to flip the pancake in the air before serving it.","exampleTranslation":"그는 서빙하기 전에 팬케이크를 공중에서 휙 뒤집는 것을 좋아합니다.","level":10,"category":"빈도 학습"},{"id":16223,"term":"fortnight","meaning":"2주일; 14일","partOfSpeech":"n.","example":"They are going on vacation for a fortnight next month.","exampleTranslation":"그들은 다음 달에 2주일 동안 휴가를 떠날 예정입니다.","level":10,"category":"빈도 학습"},{"id":16224,"term":"fox","meaning":"여우","partOfSpeech":"n.","example":"A red fox crossed the quiet country road at dusk.","exampleTranslation":"붉은 여우 한 마리가 해질녘에 조용한 시골길을 가로질렀습니다.","level":10,"category":"빈도 학습"},{"id":16225,"term":"frankly","meaning":"솔직히; 솔직히 말해서","partOfSpeech":"adv.","example":"Frankly, I don't think this plan will work at all.","exampleTranslation":"솔직히 말해서, 저는 이 계획이 전혀 통하지 않을 것 같습니다.","level":10,"category":"빈도 학습"},{"id":16226,"term":"frog","meaning":"개구리","partOfSpeech":"n.","example":"A small green frog jumped into the pond behind the house.","exampleTranslation":"작은 초록색 개구리가 집 뒤 연못으로 뛰어들었습니다.","level":10,"category":"빈도 학습"},{"id":16227,"term":"frustrate","meaning":"좌절시키다; 방해하다","partOfSpeech":"v.","example":"The constant delays continue to frustrate everyone on the team.","exampleTranslation":"계속되는 지연은 팀원 모두를 계속 좌절시킵니다.","level":10,"category":"빈도 학습"},{"id":16228,"term":"fur","meaning":"털; 모피","partOfSpeech":"n.","example":"The cat's fur felt incredibly soft after the warm bath.","exampleTranslation":"따뜻하게 목욕시킨 후 고양이의 털이 놀랍도록 부드러웠습니다.","level":10,"category":"빈도 학습"},{"id":16229,"term":"garage","meaning":"차고; 정비소","partOfSpeech":"n.","example":"He parked the car in the garage before it started to rain.","exampleTranslation":"비가 오기 시작하기 전에 그는 차를 차고에 주차했습니다.","level":10,"category":"빈도 학습"},{"id":16230,"term":"ghost","meaning":"유령","partOfSpeech":"n.","example":"The children told scary stories about a ghost in the old house.","exampleTranslation":"아이들은 오래된 집에 사는 유령에 대한 무서운 이야기를 했습니다.","level":10,"category":"빈도 학습"},{"id":16231,"term":"glory","meaning":"영광; 영예","partOfSpeech":"n.","example":"The team celebrated their moment of glory after winning the championship.","exampleTranslation":"그 팀은 우승 후 영광의 순간을 축하했습니다.","level":10,"category":"빈도 학습"},{"id":16232,"term":"gorgeous","meaning":"아주 멋진; 화려한","partOfSpeech":"adj.","example":"She wore a gorgeous dress to the wedding reception.","exampleTranslation":"그녀는 결혼 피로연에 아주 멋진 드레스를 입고 왔습니다.","level":10,"category":"빈도 학습"},{"id":16233,"term":"grace","meaning":"품위를 더하다; 우아하게 장식하다","partOfSpeech":"v.","example":"Her elegant paintings continue to grace the walls of the museum.","exampleTranslation":"그녀의 우아한 그림들은 여전히 그 박물관의 벽을 장식하고 있습니다.","level":10,"category":"빈도 학습"},{"id":16234,"term":"thousand","meaning":"천의; 1000의","partOfSpeech":"adj.","example":"More than a thousand people attended the outdoor concert last night.","exampleTranslation":"어젯밤 야외 콘서트에 천 명이 넘는 사람들이 참석했습니다.","level":10,"category":"빈도 학습"},{"id":16235,"term":"three","meaning":"셋의; 3의","partOfSpeech":"adj.","example":"They have three children, two boys and one girl.","exampleTranslation":"그들은 아들 둘, 딸 하나로 세 명의 자녀를 두고 있습니다.","level":10,"category":"빈도 학습"},{"id":16236,"term":"thursday","meaning":"목요일","partOfSpeech":"n.","example":"The weekly team meeting is always held on Thursday morning.","exampleTranslation":"주간 팀 회의는 항상 목요일 아침에 열립니다.","level":10,"category":"빈도 학습"},{"id":16237,"term":"tuesday","meaning":"화요일","partOfSpeech":"n.","example":"She has a dentist appointment next Tuesday afternoon.","exampleTranslation":"그녀는 다음 주 화요일 오후에 치과 예약이 있습니다.","level":10,"category":"빈도 학습"},{"id":16238,"term":"confess","meaning":"고백하다; 자백하다","partOfSpeech":"v.","example":"He finally decided to confess his mistake to the manager.","exampleTranslation":"그는 마침내 관리자에게 자신의 실수를 고백하기로 결심했습니다.","level":11,"category":"빈도 학습"},{"id":16239,"term":"confine","meaning":"국한시키다; 가두다","partOfSpeech":"v.","example":"Please confine your comments to the topic being discussed.","exampleTranslation":"논의 중인 주제에만 의견을 국한해 주세요.","level":11,"category":"빈도 학습"},{"id":16240,"term":"confront","meaning":"맞서다; 직면하다","partOfSpeech":"v.","example":"She decided to confront her fear of public speaking head-on.","exampleTranslation":"그녀는 대중 앞에서 말하는 것에 대한 두려움에 정면으로 맞서기로 했습니다.","level":11,"category":"빈도 학습"},{"id":16241,"term":"congress","meaning":"의회; 국회","partOfSpeech":"n.","example":"Congress passed the new law after months of debate.","exampleTranslation":"의회는 수개월간의 논의 끝에 새 법안을 통과시켰습니다.","level":11,"category":"빈도 학습"},{"id":16242,"term":"consent","meaning":"동의하다; 승낙하다","partOfSpeech":"v.","example":"Both parents must consent before the child can travel abroad.","exampleTranslation":"부모 둘 다 동의해야 아이가 해외로 나갈 수 있습니다.","level":11,"category":"빈도 학습"},{"id":16243,"term":"consequent","meaning":"결과로 일어나는; 그에 따른","partOfSpeech":"adj.","example":"The storm and its consequent flooding caused major damage downtown.","exampleTranslation":"폭풍과 그로 인한 홍수는 시내에 큰 피해를 입혔습니다.","level":11,"category":"빈도 학습"},{"id":16244,"term":"conserve","meaning":"보존하다; 절약하다","partOfSpeech":"v.","example":"We should all try to conserve water during the summer drought.","exampleTranslation":"우리 모두 여름 가뭄 동안 물을 절약하려고 노력해야 합니다.","level":11,"category":"빈도 학습"},{"id":16245,"term":"constitution","meaning":"헌법; 체질","partOfSpeech":"n.","example":"The nation's constitution guarantees freedom of speech to every citizen.","exampleTranslation":"그 나라의 헌법은 모든 시민에게 언론의 자유를 보장합니다.","level":11,"category":"빈도 학습"},{"id":16246,"term":"constrain","meaning":"제약하다; 강요하다","partOfSpeech":"v.","example":"Limited funding continues to constrain the research team's progress.","exampleTranslation":"제한된 자금은 계속해서 연구팀의 진행을 제약하고 있습니다.","level":11,"category":"빈도 학습"},{"id":16247,"term":"consumption","meaning":"소비; 소모","partOfSpeech":"n.","example":"The government wants to reduce fuel consumption across the country.","exampleTranslation":"정부는 전국적으로 연료 소비를 줄이고자 합니다.","level":11,"category":"빈도 학습"},{"id":16248,"term":"contend","meaning":"주장하다; 다투다","partOfSpeech":"v.","example":"Lawyers for the defense contend that the evidence was mishandled.","exampleTranslation":"피고 측 변호인들은 증거가 잘못 처리되었다고 주장합니다.","level":11,"category":"빈도 학습"},{"id":16249,"term":"continent","meaning":"대륙","partOfSpeech":"n.","example":"Africa is the second largest continent on Earth.","exampleTranslation":"아프리카는 지구에서 두 번째로 큰 대륙입니다.","level":11,"category":"빈도 학습"},{"id":16250,"term":"grocer","meaning":"식료품상; 식료품점 주인","partOfSpeech":"n.","example":"The local grocer always saves the freshest vegetables for regular customers.","exampleTranslation":"동네 식료품상은 항상 단골손님을 위해 가장 신선한 채소를 남겨둡니다.","level":11,"category":"빈도 학습"},{"id":16251,"term":"handy","meaning":"편리한; 손재주가 있는","partOfSpeech":"adj.","example":"This small tool is really handy for fixing loose screws.","exampleTranslation":"이 작은 도구는 헐거운 나사를 고치는 데 정말 편리합니다.","level":11,"category":"빈도 학습"},{"id":16252,"term":"heap","meaning":"쌓다; 쌓아 올리다","partOfSpeech":"v.","example":"She likes to heap extra cheese on top of her pizza.","exampleTranslation":"그녀는 피자 위에 치즈를 잔뜩 쌓아 올리는 것을 좋아합니다.","level":11,"category":"빈도 학습"},{"id":16253,"term":"heaven","meaning":"천국; 하늘","partOfSpeech":"n.","example":"In many religions, people believe good deeds lead to heaven.","exampleTranslation":"많은 종교에서 사람들은 선행이 천국으로 이어진다고 믿습니다.","level":11,"category":"빈도 학습"},{"id":16254,"term":"hedge","meaning":"울타리를 치다; 회피하다","partOfSpeech":"v.","example":"The politician tried to hedge on the question instead of giving a direct answer.","exampleTranslation":"그 정치인은 직접적인 답변 대신 질문을 회피하려 했습니다.","level":11,"category":"빈도 학습"},{"id":16255,"term":"hobby","meaning":"취미","partOfSpeech":"n.","example":"Gardening has become her favorite hobby since she retired.","exampleTranslation":"은퇴한 이후로 정원 가꾸기는 그녀가 가장 좋아하는 취미가 되었습니다.","level":11,"category":"빈도 학습"},{"id":16256,"term":"honey","meaning":"꿀; 자기야(애칭)","partOfSpeech":"n.","example":"She stirred a spoonful of honey into her warm tea.","exampleTranslation":"그녀는 따뜻한 차에 꿀 한 스푼을 저어 넣었습니다.","level":11,"category":"빈도 학습"},{"id":16257,"term":"idiot","meaning":"바보; 멍청이","partOfSpeech":"n.","example":"He felt like an idiot after forgetting his own phone number.","exampleTranslation":"그는 자신의 전화번호를 잊어버린 후 바보가 된 기분이었습니다.","level":11,"category":"빈도 학습"},{"id":16258,"term":"incredible","meaning":"믿을 수 없는; 놀라운","partOfSpeech":"adj.","example":"The view from the mountain top was absolutely incredible.","exampleTranslation":"산 정상에서 보이는 경치는 그야말로 믿을 수 없을 정도로 놀라웠습니다.","level":11,"category":"빈도 학습"},{"id":16259,"term":"inspect","meaning":"검사하다; 점검하다","partOfSpeech":"v.","example":"The officer will inspect every vehicle before it leaves the factory.","exampleTranslation":"그 담당자는 공장을 떠나기 전에 모든 차량을 검사할 것입니다.","level":11,"category":"빈도 학습"},{"id":16260,"term":"instant","meaning":"즉각적인; 순간의","partOfSpeech":"adj.","example":"The new app gives customers instant access to their account balance.","exampleTranslation":"그 새 앱은 고객에게 계좌 잔액에 대한 즉각적인 접근을 제공합니다.","level":11,"category":"빈도 학습"},{"id":16261,"term":"instruct","meaning":"지시하다; 가르치다","partOfSpeech":"v.","example":"The manager will instruct new employees on safety procedures.","exampleTranslation":"그 관리자는 신입 직원들에게 안전 절차를 지시할 것입니다.","level":11,"category":"빈도 학습"},{"id":16262,"term":"twelve","meaning":"열둘의; 12의","partOfSpeech":"adj.","example":"The store opens at twelve o'clock every day.","exampleTranslation":"그 가게는 매일 12시에 문을 엽니다.","level":11,"category":"빈도 학습"},{"id":16263,"term":"twenty","meaning":"스물의; 20의","partOfSpeech":"adj.","example":"She has saved twenty dollars from her weekly allowance.","exampleTranslation":"그녀는 매주 받는 용돈에서 20달러를 모았습니다.","level":11,"category":"빈도 학습"},{"id":16264,"term":"two","meaning":"둘의; 2의","partOfSpeech":"adj.","example":"They ordered two coffees and a slice of cake.","exampleTranslation":"그들은 커피 두 잔과 케이크 한 조각을 주문했습니다.","level":11,"category":"빈도 학습"},{"id":16265,"term":"controversy","meaning":"논란; 논쟁","partOfSpeech":"n.","example":"The new policy sparked controversy among local residents.","exampleTranslation":"그 새 정책은 지역 주민들 사이에서 논란을 일으켰습니다.","level":12,"category":"빈도 학습"},{"id":16266,"term":"convey","meaning":"전달하다; 운반하다","partOfSpeech":"v.","example":"Her letter managed to convey exactly how grateful she felt.","exampleTranslation":"그녀의 편지는 그녀가 얼마나 고마워하는지를 정확히 전달했습니다.","level":12,"category":"빈도 학습"},{"id":16267,"term":"convict","meaning":"유죄를 선고하다","partOfSpeech":"v.","example":"The jury needed only two hours to convict the defendant.","exampleTranslation":"배심원단은 피고인에게 유죄를 선고하는 데 단 두 시간밖에 걸리지 않았습니다.","level":12,"category":"빈도 학습"},{"id":16268,"term":"cooperate","meaning":"협력하다","partOfSpeech":"v.","example":"The two departments agreed to cooperate on the new project.","exampleTranslation":"두 부서는 새 프로젝트에서 협력하기로 합의했습니다.","level":12,"category":"빈도 학습"},{"id":16269,"term":"coordinate","meaning":"조정하다; 조직화하다","partOfSpeech":"v.","example":"She was asked to coordinate the volunteers for the charity event.","exampleTranslation":"그녀는 자선 행사를 위해 자원봉사자들을 조정해 달라는 요청을 받았습니다.","level":12,"category":"빈도 학습"},{"id":16270,"term":"correlate","meaning":"상관관계가 있다; 연관시키다","partOfSpeech":"v.","example":"Researchers found that exercise tends to correlate with better sleep.","exampleTranslation":"연구자들은 운동이 더 나은 수면과 상관관계가 있는 경향을 발견했습니다.","level":12,"category":"빈도 학습"},{"id":16271,"term":"correspondent","meaning":"특파원; 통신원","partOfSpeech":"n.","example":"The correspondent reported live from the disaster area.","exampleTranslation":"그 특파원은 재난 지역에서 생중계로 보도했습니다.","level":12,"category":"빈도 학습"},{"id":16272,"term":"corridor","meaning":"복도","partOfSpeech":"n.","example":"Students are not allowed to run in the school corridor.","exampleTranslation":"학생들은 학교 복도에서 뛰는 것이 허용되지 않습니다.","level":12,"category":"빈도 학습"},{"id":16273,"term":"corrupt","meaning":"부패한; 타락한","partOfSpeech":"adj.","example":"The journalist exposed several corrupt officials in the city government.","exampleTranslation":"그 기자는 시 정부의 여러 부패한 공무원들을 폭로했습니다.","level":12,"category":"빈도 학습"},{"id":16274,"term":"courage","meaning":"용기","partOfSpeech":"n.","example":"It took great courage for her to speak up during the meeting.","exampleTranslation":"그녀가 회의 중에 목소리를 내는 데는 큰 용기가 필요했습니다.","level":12,"category":"빈도 학습"},{"id":16275,"term":"cruise","meaning":"순항하다; 유람하다","partOfSpeech":"v.","example":"The couple plans to cruise around the Caribbean next spring.","exampleTranslation":"그 부부는 내년 봄 카리브해를 유람할 계획입니다.","level":12,"category":"빈도 학습"},{"id":16276,"term":"crush","meaning":"으스러뜨리다; 짓누르다","partOfSpeech":"v.","example":"Be careful not to crush the fresh berries in the bag.","exampleTranslation":"가방 안의 신선한 베리를 으스러뜨리지 않도록 조심하세요.","level":12,"category":"빈도 학습"},{"id":16277,"term":"crystal","meaning":"수정; 결정체","partOfSpeech":"n.","example":"The necklace was made from a single piece of clear crystal.","exampleTranslation":"그 목걸이는 투명한 수정 한 조각으로 만들어졌습니다.","level":12,"category":"빈도 학습"},{"id":16278,"term":"curriculum","meaning":"교육과정; 커리큘럼","partOfSpeech":"n.","example":"The school updated its curriculum to include more computer science courses.","exampleTranslation":"그 학교는 컴퓨터 과학 과목을 더 포함하도록 교육과정을 개편했습니다.","level":12,"category":"빈도 학습"},{"id":16279,"term":"defendant","meaning":"피고","partOfSpeech":"n.","example":"The defendant remained silent throughout the entire trial.","exampleTranslation":"피고는 재판 내내 침묵을 지켰습니다.","level":12,"category":"빈도 학습"},{"id":16280,"term":"delegate","meaning":"위임하다; 대표를 보내다","partOfSpeech":"v.","example":"A good manager knows how to delegate tasks to the team.","exampleTranslation":"좋은 관리자는 팀에 업무를 위임하는 법을 압니다.","level":12,"category":"빈도 학습"},{"id":16281,"term":"deliberate","meaning":"의도적인; 신중한","partOfSpeech":"adj.","example":"The delay was a deliberate move to gain more time.","exampleTranslation":"그 지연은 시간을 더 벌기 위한 의도적인 조치였습니다.","level":12,"category":"빈도 학습"},{"id":16282,"term":"democrat","meaning":"민주당원; 민주주의자","partOfSpeech":"n.","example":"She has voted as a loyal democrat in every election since college.","exampleTranslation":"그녀는 대학 시절부터 모든 선거에서 충실한 민주당원으로 투표해 왔습니다.","level":12,"category":"빈도 학습"},{"id":16283,"term":"intent","meaning":"몰두하는; 의도된","partOfSpeech":"adj.","example":"He was intent on finishing the marathon no matter what.","exampleTranslation":"그는 무슨 일이 있어도 마라톤을 끝내는 데 몰두해 있었습니다.","level":12,"category":"빈도 학습"},{"id":16284,"term":"interrupt","meaning":"방해하다; 중단시키다","partOfSpeech":"v.","example":"Please don't interrupt me while I'm on the phone.","exampleTranslation":"제가 통화 중일 때는 방해하지 말아 주세요.","level":12,"category":"빈도 학습"},{"id":16285,"term":"jam","meaning":"쑤셔 넣다; 막히게 하다","partOfSpeech":"v.","example":"Too many cars tried to jam into the narrow parking lot.","exampleTranslation":"너무 많은 차들이 좁은 주차장으로 비집고 들어가려 했습니다.","level":12,"category":"빈도 학습"},{"id":16286,"term":"january","meaning":"1월","partOfSpeech":"n.","example":"The new semester usually begins in late January.","exampleTranslation":"새 학기는 보통 1월 말에 시작됩니다.","level":12,"category":"빈도 학습"},{"id":16287,"term":"jaw","meaning":"턱","partOfSpeech":"n.","example":"He clenched his jaw tightly as he waited for the results.","exampleTranslation":"그는 결과를 기다리며 턱을 꽉 다물었습니다.","level":12,"category":"빈도 학습"},{"id":16288,"term":"jeans","meaning":"청바지","partOfSpeech":"n.","example":"She wore a pair of comfortable jeans to the picnic.","exampleTranslation":"그녀는 소풍에 편안한 청바지를 입고 갔습니다.","level":12,"category":"빈도 학습"},{"id":16289,"term":"juice","meaning":"주스; 즙","partOfSpeech":"n.","example":"He squeezed fresh orange juice for breakfast every morning.","exampleTranslation":"그는 매일 아침 신선한 오렌지 주스를 짜서 마셨습니다.","level":12,"category":"빈도 학습"},{"id":16290,"term":"july","meaning":"7월","partOfSpeech":"n.","example":"Most schools in the country are on break during July.","exampleTranslation":"그 나라의 대부분 학교는 7월 동안 방학입니다.","level":12,"category":"빈도 학습"},{"id":16291,"term":"june","meaning":"6월","partOfSpeech":"n.","example":"Her graduation ceremony will be held in early June.","exampleTranslation":"그녀의 졸업식은 6월 초에 열릴 예정입니다.","level":12,"category":"빈도 학습"},{"id":16292,"term":"junior","meaning":"하급의; 후배의","partOfSpeech":"adj.","example":"She was recently promoted from a junior position to team leader.","exampleTranslation":"그녀는 최근 하급 직급에서 팀장으로 승진했습니다.","level":12,"category":"빈도 학습"},{"id":16293,"term":"underneath","meaning":"~아래에; ~밑에","partOfSpeech":"prep.","example":"The cat was hiding underneath the wooden porch during the storm.","exampleTranslation":"폭풍우가 치는 동안 고양이는 나무 현관 밑에 숨어 있었습니다.","level":12,"category":"빈도 학습"},{"id":16294,"term":"unless","meaning":"~하지 않는 한","partOfSpeech":"conj.","example":"You will not pass the final exam unless you study a little every single day.","exampleTranslation":"매일 조금씩 공부하지 않는 한 기말시험에 합격하지 못할 것입니다.","level":12,"category":"빈도 학습"},{"id":16295,"term":"until","meaning":"~까지","partOfSpeech":"conj.","example":"She waited at the station until the last train finally arrived.","exampleTranslation":"그녀는 마지막 기차가 마침내 도착할 때까지 역에서 기다렸습니다.","level":12,"category":"빈도 학습"},{"id":16296,"term":"dense","meaning":"밀집한; 빽빽한","partOfSpeech":"adj.","example":"The hikers got lost in the dense forest without a map.","exampleTranslation":"그 등산객들은 지도 없이 빽빽한 숲에서 길을 잃었습니다.","level":13,"category":"빈도 학습"},{"id":16297,"term":"depict","meaning":"묘사하다; 그리다","partOfSpeech":"v.","example":"The artist wanted to depict the history of the small fishing village in her mural.","exampleTranslation":"그 예술가는 벽화에 그 작은 어촌 마을의 역사를 묘사하고 싶어했습니다.","level":13,"category":"빈도 학습"},{"id":16298,"term":"deputy","meaning":"대리; 부관","partOfSpeech":"n.","example":"The deputy took charge of the office while the manager was away.","exampleTranslation":"그 대리는 관리자가 자리를 비운 동안 사무실을 책임졌습니다.","level":13,"category":"빈도 학습"},{"id":16299,"term":"descend","meaning":"내려가다; 하강하다","partOfSpeech":"v.","example":"The hikers began to descend the mountain as the sun started to set.","exampleTranslation":"해가 지기 시작하자 등산객들은 산을 내려가기 시작했습니다.","level":13,"category":"빈도 학습"},{"id":16300,"term":"designate","meaning":"지정하다; 지명하다","partOfSpeech":"v.","example":"The mayor will designate a new area for the community park.","exampleTranslation":"시장은 지역 공원을 위한 새로운 부지를 지정할 것입니다.","level":13,"category":"빈도 학습"},{"id":16301,"term":"devastate","meaning":"황폐화시키다; 큰 충격을 주다","partOfSpeech":"v.","example":"The hurricane will devastate coastal towns if it makes landfall tonight.","exampleTranslation":"허리케인이 오늘 밤 상륙하면 해안 마을을 황폐화시킬 것입니다.","level":13,"category":"빈도 학습"},{"id":16303,"term":"dictate","meaning":"받아쓰게 하다; 지시하다","partOfSpeech":"v.","example":"The manager will dictate a letter for the secretary to type.","exampleTranslation":"관리자는 비서가 타이핑할 편지를 받아쓰게 할 것입니다.","level":13,"category":"빈도 학습"},{"id":16304,"term":"diplomat","meaning":"외교관","partOfSpeech":"n.","example":"A skilled diplomat can resolve conflicts through careful negotiation.","exampleTranslation":"노련한 외교관은 신중한 협상을 통해 갈등을 해결할 수 있습니다.","level":13,"category":"빈도 학습"},{"id":16305,"term":"disabled","meaning":"장애가 있는","partOfSpeech":"adj.","example":"The building added ramps to make it accessible for disabled visitors.","exampleTranslation":"그 건물은 장애가 있는 방문객이 이용할 수 있도록 경사로를 추가했습니다.","level":13,"category":"빈도 학습"},{"id":16306,"term":"disc","meaning":"원반; 디스크","partOfSpeech":"n.","example":"He slipped a disc while lifting a heavy box at work.","exampleTranslation":"그는 직장에서 무거운 상자를 들다가 디스크가 삐끗했습니다.","level":13,"category":"빈도 학습"},{"id":16307,"term":"discourse","meaning":"담화; 담론","partOfSpeech":"n.","example":"The professor's lecture explored the discourse surrounding climate policy.","exampleTranslation":"교수의 강의는 기후 정책을 둘러싼 담론을 다뤘습니다.","level":13,"category":"빈도 학습"},{"id":16308,"term":"discreet","meaning":"신중한; 조심스러운","partOfSpeech":"adj.","example":"Please be discreet when discussing the merger with outside partners.","exampleTranslation":"외부 협력사와 합병에 대해 이야기할 때는 신중하게 해 주세요.","level":13,"category":"빈도 학습"},{"id":16309,"term":"discriminate","meaning":"차별하다; 구별하다","partOfSpeech":"v.","example":"It is illegal for employers to discriminate against workers based on age.","exampleTranslation":"고용주가 나이를 이유로 근로자를 차별하는 것은 불법입니다.","level":13,"category":"빈도 학습"},{"id":16310,"term":"dispose","meaning":"처리하다; 배치하다","partOfSpeech":"v.","example":"You should dispose of chemical waste according to local regulations.","exampleTranslation":"화학 폐기물은 지역 규정에 따라 처리해야 합니다.","level":13,"category":"빈도 학습"},{"id":16311,"term":"disrupt","meaning":"방해하다; 지장을 주다","partOfSpeech":"v.","example":"The power outage will disrupt production at the factory today.","exampleTranslation":"정전으로 오늘 공장의 생산에 지장이 생길 것입니다.","level":13,"category":"빈도 학습"},{"id":16312,"term":"diverse","meaning":"다양한","partOfSpeech":"adj.","example":"The university attracts a diverse group of students from many countries.","exampleTranslation":"그 대학교는 여러 나라에서 온 다양한 학생 집단을 유치합니다.","level":13,"category":"빈도 학습"},{"id":16313,"term":"dna","meaning":"디엔에이; 유전자","partOfSpeech":"n.","example":"Scientists compared the DNA samples to identify the suspect.","exampleTranslation":"과학자들은 용의자를 밝히기 위해 디엔에이 샘플을 비교했습니다.","level":13,"category":"빈도 학습"},{"id":16314,"term":"doctrine","meaning":"교리; 원칙","partOfSpeech":"n.","example":"The organization follows a strict doctrine that guides every decision.","exampleTranslation":"그 단체는 모든 결정을 이끄는 엄격한 교리를 따릅니다.","level":13,"category":"빈도 학습"},{"id":16315,"term":"dominant","meaning":"지배적인; 우세한","partOfSpeech":"adj.","example":"The lion is the dominant male in this pride.","exampleTranslation":"그 사자는 이 무리에서 지배적인 수컷입니다.","level":13,"category":"빈도 학습"},{"id":16316,"term":"kilometer","meaning":"킬로미터","partOfSpeech":"n.","example":"The finish line is just one kilometer away from here.","exampleTranslation":"결승선은 여기서 겨우 1킬로미터 떨어져 있습니다.","level":13,"category":"빈도 학습"},{"id":16317,"term":"knit","meaning":"뜨개질하다; 짜다","partOfSpeech":"v.","example":"My grandmother taught me how to knit a warm scarf.","exampleTranslation":"할머니는 저에게 따뜻한 목도리를 뜨는 법을 가르쳐 주셨습니다.","level":13,"category":"빈도 학습"},{"id":16318,"term":"lamb","meaning":"새끼 양; 양고기","partOfSpeech":"n.","example":"The farmer watched over a newborn lamb in the barn.","exampleTranslation":"농부는 헛간에서 갓 태어난 새끼 양을 돌보았습니다.","level":13,"category":"빈도 학습"},{"id":16319,"term":"lamp","meaning":"램프; 등","partOfSpeech":"n.","example":"She turned on the lamp beside her bed to read a book.","exampleTranslation":"그녀는 책을 읽기 위해 침대 옆 램프를 켰습니다.","level":13,"category":"빈도 학습"},{"id":16320,"term":"lane","meaning":"차선; 좁은 길","partOfSpeech":"n.","example":"Stay in the right lane if you plan to exit the highway soon.","exampleTranslation":"곧 고속도로에서 나갈 계획이라면 오른쪽 차선을 유지하세요.","level":13,"category":"빈도 학습"},{"id":16321,"term":"lawn","meaning":"잔디밭","partOfSpeech":"n.","example":"He spent the whole Saturday morning mowing the lawn.","exampleTranslation":"그는 토요일 아침 내내 잔디밭을 깎으며 보냈습니다.","level":13,"category":"빈도 학습"},{"id":16322,"term":"lid","meaning":"뚜껑","partOfSpeech":"n.","example":"Make sure to close the lid tightly before you shake the bottle.","exampleTranslation":"병을 흔들기 전에 뚜껑을 단단히 닫아 주세요.","level":13,"category":"빈도 학습"},{"id":16323,"term":"lightly","meaning":"가볍게; 살짝","partOfSpeech":"adv.","example":"She tapped him lightly on the shoulder to get his attention.","exampleTranslation":"그녀는 그의 주의를 끌기 위해 어깨를 가볍게 두드렸습니다.","level":13,"category":"빈도 학습"},{"id":16324,"term":"lion","meaning":"사자","partOfSpeech":"n.","example":"The lion roared loudly as the sun set over the savanna.","exampleTranslation":"사바나에 해가 질 무렵 사자가 크게 포효했습니다.","level":13,"category":"빈도 학습"},{"id":16325,"term":"lone","meaning":"혼자인; 외로운","partOfSpeech":"adj.","example":"A lone hiker walked slowly along the empty mountain trail.","exampleTranslation":"혼자인 등산객이 텅 빈 산길을 따라 천천히 걸었습니다.","level":13,"category":"빈도 학습"},{"id":16326,"term":"lower","meaning":"낮추다; 내리다","partOfSpeech":"v.","example":"Please lower your voice so we don't wake the baby.","exampleTranslation":"아기가 깨지 않도록 목소리를 낮춰 주세요.","level":13,"category":"빈도 학습"},{"id":16327,"term":"wednesday","meaning":"수요일","partOfSpeech":"n.","example":"We usually have our team meeting every Wednesday afternoon.","exampleTranslation":"우리는 보통 매주 수요일 오후에 팀 회의를 합니다.","level":13,"category":"빈도 학습"},{"id":16328,"term":"what","meaning":"무엇; (감탄문) 정말","partOfSpeech":"pron.","example":"What a beautiful sunset we saw from the rooftop last night!","exampleTranslation":"어젯밤 옥상에서 정말 아름다운 노을을 봤어요!","level":13,"category":"빈도 학습"},{"id":16329,"term":"whatever","meaning":"무엇이든","partOfSpeech":"pron.","example":"Whatever you do, don't forget to lock the door before you leave.","exampleTranslation":"무엇을 하든 나가기 전에 문 잠그는 것은 잊지 마세요.","level":13,"category":"빈도 학습"},{"id":16330,"term":"donate","meaning":"기부하다","partOfSpeech":"v.","example":"Many people donate old clothes to charity every winter.","exampleTranslation":"많은 사람들이 매년 겨울 헌 옷을 자선단체에 기부합니다.","level":14,"category":"빈도 학습"},{"id":16331,"term":"dose","meaning":"복용량; 1회분","partOfSpeech":"n.","example":"The doctor increased her dose of medicine to control the fever.","exampleTranslation":"의사는 열을 조절하기 위해 그녀의 약 복용량을 늘렸습니다.","level":14,"category":"빈도 학습"},{"id":16332,"term":"drain","meaning":"배수시키다; 소모시키다","partOfSpeech":"v.","example":"Remember to drain the pasta before adding the sauce.","exampleTranslation":"소스를 넣기 전에 파스타의 물을 빼는 것을 잊지 마세요.","level":14,"category":"빈도 학습"},{"id":16333,"term":"drift","meaning":"표류하다; 떠돌다","partOfSpeech":"v.","example":"The small boat began to drift away from the dock in the current.","exampleTranslation":"작은 배가 물살에 밀려 부두에서 멀어지기 시작했습니다.","level":14,"category":"빈도 학습"},{"id":16334,"term":"drill","meaning":"훈련시키다; 반복 연습시키다","partOfSpeech":"v.","example":"The coach will drill the players on basic passing skills every practice.","exampleTranslation":"코치는 매 훈련마다 선수들에게 기본 패스 기술을 반복 훈련시킬 것입니다.","level":14,"category":"빈도 학습"},{"id":16335,"term":"duke","meaning":"공작","partOfSpeech":"n.","example":"The duke welcomed foreign guests at the entrance of his castle.","exampleTranslation":"공작은 자신의 성 입구에서 외국 손님들을 맞이했습니다.","level":14,"category":"빈도 학습"},{"id":16336,"term":"eager","meaning":"열망하는; 간절히 바라는","partOfSpeech":"adj.","example":"The new intern seemed eager to learn everything about the job.","exampleTranslation":"새 인턴은 그 일에 대해 모든 것을 배우고 싶어 열망하는 것 같았습니다.","level":14,"category":"빈도 학습"},{"id":16337,"term":"echo","meaning":"울려 퍼지다; 반향하다","partOfSpeech":"v.","example":"Her laughter continued to echo through the empty hallway.","exampleTranslation":"그녀의 웃음소리가 텅 빈 복도에 계속 울려 퍼졌습니다.","level":14,"category":"빈도 학습"},{"id":16338,"term":"elaborate","meaning":"자세히 설명하다; 상술하다","partOfSpeech":"v.","example":"Could you elaborate on your plan for the new project?","exampleTranslation":"새 프로젝트에 대한 계획을 좀 더 자세히 설명해 주시겠어요?","level":14,"category":"빈도 학습"},{"id":16339,"term":"elevate","meaning":"높이다; 승격시키다","partOfSpeech":"v.","example":"Regular exercise can elevate your mood and reduce stress.","exampleTranslation":"규칙적인 운동은 기분을 좋게 하고 스트레스를 줄여줄 수 있습니다.","level":14,"category":"빈도 학습"},{"id":16340,"term":"elite","meaning":"엘리트의; 최상위의","partOfSpeech":"adj.","example":"Only elite athletes are invited to compete in this tournament.","exampleTranslation":"이 대회에는 최상위 엘리트 선수들만 초청받습니다.","level":14,"category":"빈도 학습"},{"id":16341,"term":"emit","meaning":"방출하다; 내뿜다","partOfSpeech":"v.","example":"Old factories emit large amounts of smoke into the air.","exampleTranslation":"오래된 공장들은 많은 양의 연기를 공기 중으로 방출합니다.","level":14,"category":"빈도 학습"},{"id":16342,"term":"endorse","meaning":"지지하다; (제품을) 보증 추천하다","partOfSpeech":"v.","example":"The famous athlete agreed to endorse the new sports drink.","exampleTranslation":"그 유명한 운동선수는 새 스포츠 음료를 홍보하기로 동의했습니다.","level":14,"category":"빈도 학습"},{"id":16343,"term":"endure","meaning":"견디다; 참다","partOfSpeech":"v.","example":"The soldiers had to endure freezing temperatures during the mission.","exampleTranslation":"군인들은 임무 중 혹독한 추위를 견뎌야 했습니다.","level":14,"category":"빈도 학습"},{"id":16344,"term":"enforce","meaning":"집행하다; 시행하다","partOfSpeech":"v.","example":"The city plans to enforce the new parking rules starting next month.","exampleTranslation":"시는 다음 달부터 새로운 주차 규정을 시행할 계획입니다.","level":14,"category":"빈도 학습"},{"id":16345,"term":"enthusiasm","meaning":"열정; 열의","partOfSpeech":"n.","example":"She joined the club with great enthusiasm and made many new friends.","exampleTranslation":"그녀는 큰 열정을 가지고 동아리에 가입해서 많은 새 친구를 사귀었습니다.","level":14,"category":"빈도 학습"},{"id":16346,"term":"enthusiastic","meaning":"열정적인","partOfSpeech":"adj.","example":"The coach was enthusiastic about the team's chances this season.","exampleTranslation":"코치는 이번 시즌 팀의 가능성에 대해 열정적이었습니다.","level":14,"category":"빈도 학습"},{"id":16347,"term":"evident","meaning":"분명한; 명백한","partOfSpeech":"adj.","example":"It was evident from her smile that she had passed the exam.","exampleTranslation":"그녀의 미소를 보니 시험에 합격했다는 것이 분명했습니다.","level":14,"category":"빈도 학습"},{"id":16348,"term":"exclusive","meaning":"독점적인; 배타적인","partOfSpeech":"adj.","example":"The magazine published an exclusive interview with the director.","exampleTranslation":"그 잡지는 감독과의 독점 인터뷰를 게재했습니다.","level":14,"category":"빈도 학습"},{"id":16349,"term":"execute","meaning":"실행하다; 처형하다","partOfSpeech":"v.","example":"The team worked hard to execute the marketing plan flawlessly.","exampleTranslation":"팀은 마케팅 계획을 완벽하게 실행하기 위해 열심히 노력했습니다.","level":14,"category":"빈도 학습"},{"id":16350,"term":"explicit","meaning":"명확한; 노골적인","partOfSpeech":"adj.","example":"The manager gave explicit instructions on how to handle customer complaints.","exampleTranslation":"관리자는 고객 불만을 처리하는 방법에 대해 명확한 지시를 내렸습니다.","level":14,"category":"빈도 학습"},{"id":16351,"term":"exploit","meaning":"착취하다; (이익을 위해) 이용하다","partOfSpeech":"v.","example":"Some companies exploit workers by paying wages far below the minimum.","exampleTranslation":"일부 기업은 최저 임금보다 훨씬 낮은 임금을 지급하며 노동자를 착취합니다.","level":14,"category":"빈도 학습"},{"id":16352,"term":"explosion","meaning":"폭발","partOfSpeech":"n.","example":"A loud explosion shook the entire building last night.","exampleTranslation":"어젯밤 큰 폭발이 건물 전체를 흔들었습니다.","level":14,"category":"빈도 학습"},{"id":16353,"term":"fabric","meaning":"직물; 천","partOfSpeech":"n.","example":"This dress is made from a soft, breathable fabric.","exampleTranslation":"이 드레스는 부드럽고 통기성이 좋은 천으로 만들어졌습니다.","level":14,"category":"빈도 학습"},{"id":16354,"term":"facilitate","meaning":"촉진하다; 용이하게 하다","partOfSpeech":"v.","example":"The new software will facilitate communication between departments.","exampleTranslation":"새 소프트웨어는 부서 간 소통을 촉진할 것입니다.","level":14,"category":"빈도 학습"},{"id":16355,"term":"lump","meaning":"덩어리","partOfSpeech":"n.","example":"She added a lump of butter to the hot pan before frying the onions.","exampleTranslation":"그녀는 양파를 볶기 전에 뜨거운 팬에 버터 한 덩어리를 넣었습니다.","level":14,"category":"빈도 학습"},{"id":16356,"term":"mama","meaning":"엄마","partOfSpeech":"n.","example":"The little boy ran to his mama as soon as he saw her.","exampleTranslation":"그 어린 소년은 엄마를 보자마자 달려갔습니다.","level":14,"category":"빈도 학습"},{"id":16357,"term":"marvel","meaning":"경탄하다; 놀라워하다","partOfSpeech":"v.","example":"Tourists marvel at the ancient pyramids every year.","exampleTranslation":"관광객들은 매년 고대 피라미드를 보며 경탄합니다.","level":14,"category":"빈도 학습"},{"id":16358,"term":"mask","meaning":"가리다; 감추다","partOfSpeech":"v.","example":"She tried to mask her disappointment with a polite smile.","exampleTranslation":"그녀는 정중한 미소로 실망감을 감추려 했습니다.","level":14,"category":"빈도 학습"},{"id":16359,"term":"melt","meaning":"녹다; 녹이다","partOfSpeech":"v.","example":"The ice cream began to melt quickly in the summer heat.","exampleTranslation":"아이스크림이 여름 더위 속에서 빠르게 녹기 시작했습니다.","level":14,"category":"빈도 학습"},{"id":16360,"term":"merry","meaning":"즐거운; 명랑한","partOfSpeech":"adj.","example":"The children sang merry songs around the Christmas tree.","exampleTranslation":"아이들은 크리스마스트리 주위에서 즐거운 노래를 불렀습니다.","level":14,"category":"빈도 학습"},{"id":16361,"term":"microwave","meaning":"전자레인지에 데우다","partOfSpeech":"v.","example":"Just microwave the leftovers for two minutes before you eat.","exampleTranslation":"먹기 전에 남은 음식을 전자레인지에 2분만 데우면 됩니다.","level":14,"category":"빈도 학습"},{"id":16362,"term":"mill","meaning":"제분하다; 갈다","partOfSpeech":"v.","example":"Farmers used to mill wheat into flour by hand long ago.","exampleTranslation":"옛날에는 농부들이 손으로 밀을 갈아 밀가루를 만들었습니다.","level":14,"category":"빈도 학습"},{"id":16363,"term":"minus","meaning":"~을 뺀; 마이너스의","partOfSpeech":"prep.","example":"Ten minus four equals six.","exampleTranslation":"10 빼기 4는 6입니다.","level":14,"category":"빈도 학습"},{"id":16364,"term":"when","meaning":"~할 때","partOfSpeech":"conj.","example":"When in Rome, do as the Romans do.","exampleTranslation":"로마에 가면 로마법을 따르라.","level":14,"category":"빈도 학습"},{"id":16365,"term":"faculty","meaning":"교수진; 능력","partOfSpeech":"n.","example":"The university hired ten new professors to join the faculty this year.","exampleTranslation":"그 대학교는 올해 교수진에 합류할 새 교수 열 명을 채용했습니다.","level":15,"category":"빈도 학습"},{"id":16366,"term":"fantasy","meaning":"환상; 공상","partOfSpeech":"n.","example":"He often escapes into a fantasy world through video games.","exampleTranslation":"그는 종종 비디오 게임을 통해 환상의 세계로 도피합니다.","level":15,"category":"빈도 학습"},{"id":16367,"term":"fate","meaning":"운명","partOfSpeech":"n.","example":"She believed that fate had brought them together that rainy evening.","exampleTranslation":"그녀는 그 비 오는 저녁에 운명이 그들을 이어주었다고 믿었습니다.","level":15,"category":"빈도 학습"},{"id":16368,"term":"feminist","meaning":"여성주의의; 페미니즘의","partOfSpeech":"adj.","example":"She has always held strong feminist views on workplace equality.","exampleTranslation":"그녀는 항상 직장 내 평등에 관해 확고한 여성주의적 견해를 가지고 있었습니다.","level":15,"category":"빈도 학습"},{"id":16369,"term":"fertile","meaning":"비옥한; 다산의","partOfSpeech":"adj.","example":"The river valley is known for its fertile soil, perfect for farming.","exampleTranslation":"그 강 유역은 농사에 적합한 비옥한 토양으로 유명합니다.","level":15,"category":"빈도 학습"},{"id":16370,"term":"fiber","meaning":"섬유; 식이섬유","partOfSpeech":"n.","example":"Whole grains are an excellent source of dietary fiber.","exampleTranslation":"통곡물은 훌륭한 식이섬유 공급원입니다.","level":15,"category":"빈도 학습"},{"id":16371,"term":"fierce","meaning":"사나운; 격렬한","partOfSpeech":"adj.","example":"The two companies are in fierce competition for the same customers.","exampleTranslation":"그 두 회사는 같은 고객을 두고 치열한 경쟁을 벌이고 있습니다.","level":15,"category":"빈도 학습"},{"id":16372,"term":"flee","meaning":"도망치다; 달아나다","partOfSpeech":"v.","example":"Thousands of residents had to flee the city before the storm hit.","exampleTranslation":"폭풍이 닥치기 전에 수천 명의 주민들이 도시를 떠나야 했습니다.","level":15,"category":"빈도 학습"},{"id":16373,"term":"flesh","meaning":"살; 육체","partOfSpeech":"n.","example":"The wound was deep enough to expose the flesh beneath the skin.","exampleTranslation":"그 상처는 피부 아래 살이 드러날 정도로 깊었습니다.","level":15,"category":"빈도 학습"},{"id":16374,"term":"foster","meaning":"육성하다; 촉진하다","partOfSpeech":"v.","example":"Good teachers foster curiosity and confidence in their students.","exampleTranslation":"좋은 교사는 학생들에게 호기심과 자신감을 길러 줍니다.","level":15,"category":"빈도 학습"},{"id":16375,"term":"funeral","meaning":"장례식","partOfSpeech":"n.","example":"Hundreds of people attended the funeral to pay their respects.","exampleTranslation":"수백 명의 사람들이 조의를 표하기 위해 장례식에 참석했습니다.","level":15,"category":"빈도 학습"},{"id":16376,"term":"gang","meaning":"(~에게) 떼로 덤비다","partOfSpeech":"v.","example":"The older kids would gang up on him during recess.","exampleTranslation":"나이 많은 아이들은 쉬는 시간에 그를 떼로 괴롭히곤 했습니다.","level":15,"category":"빈도 학습"},{"id":16377,"term":"generous","meaning":"관대한; 후한","partOfSpeech":"adj.","example":"The old man was generous enough to donate half his fortune to charity.","exampleTranslation":"그 노인은 자선단체에 재산의 절반을 기부할 만큼 관대했습니다.","level":15,"category":"빈도 학습"},{"id":16378,"term":"geography","meaning":"지리; 지리학","partOfSpeech":"n.","example":"The mountainous geography of the region makes farming difficult.","exampleTranslation":"그 지역의 산악 지형은 농사를 어렵게 만듭니다.","level":15,"category":"빈도 학습"},{"id":16379,"term":"glow","meaning":"빛나다; 은은하게 빛을 내다","partOfSpeech":"v.","example":"The stars began to glow brightly as the sky grew dark.","exampleTranslation":"하늘이 어두워지면서 별들이 밝게 빛나기 시작했습니다.","level":15,"category":"빈도 학습"},{"id":16380,"term":"gradual","meaning":"점진적인","partOfSpeech":"adj.","example":"The company plans a gradual increase in prices over the next year.","exampleTranslation":"그 회사는 내년에 걸쳐 점진적인 가격 인상을 계획하고 있습니다.","level":15,"category":"빈도 학습"},{"id":16381,"term":"graphic","meaning":"생생한; 노골적인","partOfSpeech":"adj.","example":"The film includes graphic scenes of violence that some viewers find disturbing.","exampleTranslation":"그 영화는 일부 관객이 불편하게 느낄 만큼 노골적인 폭력 장면을 포함합니다.","level":15,"category":"빈도 학습"},{"id":16382,"term":"grasp","meaning":"붙잡다; 이해하다","partOfSpeech":"v.","example":"It took the students a while to grasp the new grammar rule.","exampleTranslation":"학생들이 새로운 문법 규칙을 이해하는 데는 시간이 좀 걸렸습니다.","level":15,"category":"빈도 학습"},{"id":16383,"term":"grave","meaning":"심각한; 중대한","partOfSpeech":"adj.","example":"The doctor's expression turned grave as he read the test results.","exampleTranslation":"의사는 검사 결과를 읽으면서 표정이 심각해졌습니다.","level":15,"category":"빈도 학습"},{"id":16384,"term":"monkey","meaning":"만지작거리다; 장난치다","partOfSpeech":"v.","example":"Stop trying to monkey around with the settings; you might break something.","exampleTranslation":"설정을 함부로 만지작거리지 마세요, 뭔가 고장 날 수도 있어요.","level":15,"category":"빈도 학습"},{"id":16385,"term":"mow","meaning":"(잔디를) 깎다","partOfSpeech":"v.","example":"My father likes to mow the lawn early on Saturday mornings.","exampleTranslation":"아버지는 토요일 아침 일찍 잔디 깎는 것을 좋아하십니다.","level":15,"category":"빈도 학습"},{"id":16386,"term":"mud","meaning":"진흙","partOfSpeech":"n.","example":"The children came home covered in mud after playing outside.","exampleTranslation":"아이들은 밖에서 놀고 나서 진흙투성이가 되어 집에 돌아왔습니다.","level":15,"category":"빈도 학습"},{"id":16387,"term":"nail","meaning":"못으로 박다; 고정시키다","partOfSpeech":"v.","example":"He used a hammer to nail the loose board back onto the fence.","exampleTranslation":"그는 망치로 헐거워진 판자를 울타리에 다시 못박았습니다.","level":15,"category":"빈도 학습"},{"id":16388,"term":"nanny","meaning":"보모","partOfSpeech":"n.","example":"They hired a nanny to look after their toddler during the week.","exampleTranslation":"그들은 평일 동안 아이를 돌봐줄 보모를 고용했습니다.","level":15,"category":"빈도 학습"},{"id":16389,"term":"nasty","meaning":"고약한; 심술궂은","partOfSpeech":"adj.","example":"He caught a nasty cold after standing in the rain too long.","exampleTranslation":"그는 빗속에 너무 오래 서 있어서 지독한 감기에 걸렸습니다.","level":15,"category":"빈도 학습"},{"id":16390,"term":"navy","meaning":"짙은 남색의","partOfSpeech":"adj.","example":"She wore a navy blazer with white trousers to the interview.","exampleTranslation":"그녀는 면접에 짙은 남색 재킷과 흰 바지를 입고 갔습니다.","level":15,"category":"빈도 학습"},{"id":16391,"term":"nest","meaning":"둥지를 틀다","partOfSpeech":"v.","example":"Robins often nest in the branches of trees near houses.","exampleTranslation":"울새는 종종 집 근처 나무 가지에 둥지를 틉니다.","level":15,"category":"빈도 학습"},{"id":16392,"term":"november","meaning":"11월","partOfSpeech":"n.","example":"Our anniversary falls on the first Saturday of November.","exampleTranslation":"우리 기념일은 11월 첫째 주 토요일입니다.","level":15,"category":"빈도 학습"},{"id":16393,"term":"nut","meaning":"견과; 너트","partOfSpeech":"n.","example":"She is allergic to any kind of nut, including peanuts and almonds.","exampleTranslation":"그녀는 땅콩과 아몬드를 포함한 모든 종류의 견과류에 알레르기가 있습니다.","level":15,"category":"빈도 학습"},{"id":16394,"term":"oak","meaning":"참나무","partOfSpeech":"n.","example":"A massive oak tree stood in the center of the old park.","exampleTranslation":"오래된 공원 한가운데에 거대한 참나무 한 그루가 서 있었습니다.","level":15,"category":"빈도 학습"},{"id":16395,"term":"october","meaning":"10월","partOfSpeech":"n.","example":"The leaves usually start changing color in October.","exampleTranslation":"낙엽은 보통 10월에 색이 변하기 시작합니다.","level":15,"category":"빈도 학습"},{"id":16396,"term":"where","meaning":"어디에서","partOfSpeech":"adv.","example":"This is the very house where I grew up as a child.","exampleTranslation":"이곳이 바로 제가 어린 시절 자란 그 집입니다.","level":15,"category":"빈도 학습"},{"id":16397,"term":"whether","meaning":"~인지 아닌지","partOfSpeech":"conj.","example":"I couldn't decide whether to laugh or cry at the joke.","exampleTranslation":"그 농담에 웃어야 할지 울어야 할지 결정할 수 없었습니다.","level":15,"category":"빈도 학습"},{"id":16398,"term":"gravity","meaning":"중력; 중대함","partOfSpeech":"n.","example":"Without gravity, objects would simply float away into space.","exampleTranslation":"중력이 없다면 물체는 그냥 우주로 떠올라 사라질 것입니다.","level":16,"category":"빈도 학습"},{"id":16399,"term":"grip","meaning":"꽉 잡다","partOfSpeech":"v.","example":"He tends to grip the steering wheel tightly whenever the storm grows worse.","exampleTranslation":"그는 폭풍이 심해질 때마다 운전대를 꽉 움켜쥐는 경향이 있습니다.","level":16,"category":"빈도 학습"},{"id":16400,"term":"gross","meaning":"역겨운; 총(전체)의","partOfSpeech":"adj.","example":"The smell from the garbage bin was so gross that everyone left the room.","exampleTranslation":"쓰레기통에서 나는 냄새가 너무 역겨워서 모두가 방을 떠났습니다.","level":16,"category":"빈도 학습"},{"id":16401,"term":"halt","meaning":"멈추다; 정지시키다","partOfSpeech":"v.","example":"The train had to halt suddenly when a deer ran across the tracks.","exampleTranslation":"사슴이 선로를 가로질러 뛰어들자 기차는 갑자기 멈춰야 했습니다.","level":16,"category":"빈도 학습"},{"id":16402,"term":"harsh","meaning":"가혹한; 거친","partOfSpeech":"adj.","example":"The coach gave harsh criticism after the team's disappointing loss.","exampleTranslation":"코치는 팀의 실망스러운 패배 후 가혹한 비판을 했습니다.","level":16,"category":"빈도 학습"},{"id":16403,"term":"hazard","meaning":"(위험을 무릅쓰고) 짐작하다","partOfSpeech":"v.","example":"I don't know the answer, but let me hazard a guess.","exampleTranslation":"정답은 모르지만 한번 추측을 해보겠습니다.","level":16,"category":"빈도 학습"},{"id":16404,"term":"heal","meaning":"치유하다; 낫다","partOfSpeech":"v.","example":"The wound will heal faster if you keep it clean and dry.","exampleTranslation":"상처는 깨끗하고 건조하게 유지하면 더 빨리 나을 것입니다.","level":16,"category":"빈도 학습"},{"id":16405,"term":"heel","meaning":"발뒤꿈치; (신발의) 굽","partOfSpeech":"n.","example":"She felt a sharp pain in her heel after running the marathon.","exampleTranslation":"그녀는 마라톤을 뛰고 나서 발뒤꿈치에 날카로운 통증을 느꼈습니다.","level":16,"category":"빈도 학습"},{"id":16406,"term":"heritage","meaning":"(문화적) 유산","partOfSpeech":"n.","example":"The old temple is an important part of the city's cultural heritage.","exampleTranslation":"그 오래된 사원은 그 도시의 문화유산 중 중요한 부분입니다.","level":16,"category":"빈도 학습"},{"id":16407,"term":"highway","meaning":"고속도로","partOfSpeech":"n.","example":"Traffic on the highway slowed to a crawl during rush hour.","exampleTranslation":"출퇴근 시간에 고속도로 교통이 거의 멈춰 섰습니다.","level":16,"category":"빈도 학습"},{"id":16408,"term":"hip","meaning":"엉덩이; 골반","partOfSpeech":"n.","example":"The elderly woman broke her hip after slipping on the icy sidewalk.","exampleTranslation":"그 노부인은 얼어붙은 보도에서 미끄러져 골반을 다쳤습니다.","level":16,"category":"빈도 학습"},{"id":16409,"term":"holy","meaning":"신성한; 성스러운","partOfSpeech":"adj.","example":"Pilgrims travel from all over the world to visit this holy site.","exampleTranslation":"순례자들은 이 신성한 장소를 방문하기 위해 전 세계에서 찾아옵니다.","level":16,"category":"빈도 학습"},{"id":16410,"term":"horror","meaning":"공포","partOfSpeech":"n.","example":"The children watched the horror movie with their hands over their eyes.","exampleTranslation":"아이들은 눈을 손으로 가린 채 공포 영화를 봤습니다.","level":16,"category":"빈도 학습"},{"id":16411,"term":"hostile","meaning":"적대적인","partOfSpeech":"adj.","example":"The two neighboring countries have had a hostile relationship for decades.","exampleTranslation":"그 두 이웃 나라는 수십 년간 적대적인 관계를 이어왔습니다.","level":16,"category":"빈도 학습"},{"id":16412,"term":"ideology","meaning":"이념; 이데올로기","partOfSpeech":"n.","example":"The two political parties differ sharply in their core ideology.","exampleTranslation":"그 두 정당은 핵심 이념에서 큰 차이를 보입니다.","level":16,"category":"빈도 학습"},{"id":16413,"term":"immune","meaning":"면역이 있는","partOfSpeech":"adj.","example":"People who had the disease before are often immune to it later.","exampleTranslation":"이전에 그 병에 걸렸던 사람들은 이후에 면역이 생기는 경우가 많습니다.","level":16,"category":"빈도 학습"},{"id":16414,"term":"impact","meaning":"영향을 미치다","partOfSpeech":"v.","example":"The new tax law will impact small businesses across the country.","exampleTranslation":"새 세법은 전국의 소규모 사업체에 영향을 미칠 것입니다.","level":16,"category":"빈도 학습"},{"id":16415,"term":"imperial","meaning":"제국의","partOfSpeech":"adj.","example":"Visitors can still see remnants of the old imperial palace downtown.","exampleTranslation":"방문객들은 시내에서 옛 황궁의 흔적을 여전히 볼 수 있습니다.","level":16,"category":"빈도 학습"},{"id":16416,"term":"implicate","meaning":"연루시키다","partOfSpeech":"v.","example":"New evidence seemed to implicate the manager in the financial scandal.","exampleTranslation":"새로운 증거는 관리자가 그 금융 스캔들에 연루된 것처럼 보이게 했습니다.","level":16,"category":"빈도 학습"},{"id":16417,"term":"inevitable","meaning":"불가피한","partOfSpeech":"adj.","example":"With sales dropping every month, layoffs seemed inevitable.","exampleTranslation":"매달 매출이 떨어지면서 정리해고는 불가피해 보였습니다.","level":16,"category":"빈도 학습"},{"id":16418,"term":"infect","meaning":"감염시키다","partOfSpeech":"v.","example":"A single sick worker can infect the entire office within days.","exampleTranslation":"아픈 직원 한 명이 며칠 안에 사무실 전체를 감염시킬 수 있습니다.","level":16,"category":"빈도 학습"},{"id":16419,"term":"inflate","meaning":"부풀리다; 팽창시키다","partOfSpeech":"v.","example":"He used a small pump to inflate the tires before the trip.","exampleTranslation":"그는 여행을 떠나기 전에 작은 펌프로 타이어에 바람을 넣었습니다.","level":16,"category":"빈도 학습"},{"id":16420,"term":"inhabit","meaning":"거주하다; 서식하다","partOfSpeech":"v.","example":"Polar bears inhabit the icy regions near the North Pole.","exampleTranslation":"북극곰은 북극 근처의 얼음 지역에 서식합니다.","level":16,"category":"빈도 학습"},{"id":16421,"term":"inherit","meaning":"상속받다; 물려받다","partOfSpeech":"v.","example":"She will inherit her grandmother's house after she passes away.","exampleTranslation":"그녀는 할머니가 돌아가신 후 집을 물려받을 것입니다.","level":16,"category":"빈도 학습"},{"id":16422,"term":"initiate","meaning":"시작하다; 착수시키다","partOfSpeech":"v.","example":"The company decided to initiate a full investigation into the complaint.","exampleTranslation":"그 회사는 그 불만 사항에 대해 전면 조사를 시작하기로 했습니다.","level":16,"category":"빈도 학습"},{"id":16423,"term":"onion","meaning":"양파","partOfSpeech":"n.","example":"Chop the onion finely before adding it to the soup.","exampleTranslation":"수프에 넣기 전에 양파를 잘게 다지세요.","level":16,"category":"빈도 학습"},{"id":16424,"term":"onto","meaning":"~위로; ~쪽으로 (hold onto: 꽉 붙잡다)","partOfSpeech":"prep.","example":"Hold onto the railing tightly as you climb the stairs.","exampleTranslation":"계단을 오를 때 난간을 꽉 붙잡으세요.","level":16,"category":"빈도 학습"},{"id":16425,"term":"ourselves","meaning":"우리 자신","partOfSpeech":"pron.","example":"We reminded ourselves to stay calm during the fire drill.","exampleTranslation":"우리는 화재 훈련 중 침착하자고 서로에게 다짐했습니다.","level":16,"category":"빈도 학습"},{"id":16426,"term":"oven","meaning":"오븐","partOfSpeech":"n.","example":"Preheat the oven to 180 degrees before baking the bread.","exampleTranslation":"빵을 굽기 전에 오븐을 180도로 예열하세요.","level":16,"category":"빈도 학습"},{"id":16427,"term":"pan","meaning":"냄비; 팬","partOfSpeech":"n.","example":"She stirred the sauce in a large pan on the stove.","exampleTranslation":"그녀는 스토브 위 큰 냄비에서 소스를 저었습니다.","level":16,"category":"빈도 학습"},{"id":16428,"term":"pat","meaning":"쓰다듬다; 토닥이다","partOfSpeech":"v.","example":"He likes to pat the dog gently on the head every morning.","exampleTranslation":"그는 매일 아침 개의 머리를 부드럽게 쓰다듬는 것을 좋아합니다.","level":16,"category":"빈도 학습"},{"id":16429,"term":"pet","meaning":"쓰다듬다","partOfSpeech":"v.","example":"She loves to pet the neighbor's cat every morning on her way to school.","exampleTranslation":"그녀는 등교하는 길에 매일 아침 이웃집 고양이를 쓰다듬는 것을 좋아합니다.","level":16,"category":"빈도 학습"},{"id":16430,"term":"pie","meaning":"파이","partOfSpeech":"n.","example":"Grandma baked an apple pie for the family gathering.","exampleTranslation":"할머니는 가족 모임을 위해 사과 파이를 구우셨습니다.","level":16,"category":"빈도 학습"},{"id":16431,"term":"pin","meaning":"핀으로 고정하다","partOfSpeech":"v.","example":"She used a clip to pin her hair back before the job interview.","exampleTranslation":"그녀는 면접 전에 클립으로 머리를 뒤로 고정했습니다.","level":16,"category":"빈도 학습"},{"id":16432,"term":"pine","meaning":"그리워하다; 갈망하다","partOfSpeech":"v.","example":"He continued to pine for his hometown long after moving abroad.","exampleTranslation":"그는 해외로 이주한 후에도 오랫동안 고향을 그리워했습니다.","level":16,"category":"빈도 학습"},{"id":16433,"term":"pity","meaning":"불쌍히 여기다","partOfSpeech":"v.","example":"I pity anyone who has to share an office with him.","exampleTranslation":"그와 사무실을 함께 써야 하는 사람이라면 누구든 안쓰럽게 느껴집니다.","level":16,"category":"빈도 학습"},{"id":16434,"term":"plug","meaning":"(전원을) 연결하다; 꽂다","partOfSpeech":"v.","example":"Please plug in the lamp before it gets dark outside.","exampleTranslation":"밖이 어두워지기 전에 램프의 플러그를 꽂아 주세요.","level":16,"category":"빈도 학습"},{"id":16435,"term":"which","meaning":"어느 것","partOfSpeech":"pron.","example":"Of the two jackets on the rack, which one do you prefer?","exampleTranslation":"선반에 있는 두 재킷 중에서 어느 것이 더 마음에 드세요?","level":16,"category":"빈도 학습"},{"id":16436,"term":"inject","meaning":"주입하다; 주사하다","partOfSpeech":"v.","example":"The nurse will inject the vaccine into your upper arm.","exampleTranslation":"간호사가 팔 윗부분에 백신을 주사할 것입니다.","level":17,"category":"빈도 학습"},{"id":16437,"term":"innovate","meaning":"혁신하다","partOfSpeech":"v.","example":"Small startups often innovate faster than large corporations.","exampleTranslation":"소규모 스타트업은 종종 대기업보다 더 빠르게 혁신합니다.","level":17,"category":"빈도 학습"},{"id":16438,"term":"insert","meaning":"삽입하다","partOfSpeech":"v.","example":"Please insert your card into the machine to begin the payment.","exampleTranslation":"결제를 시작하려면 카드를 기계에 삽입해 주세요.","level":17,"category":"빈도 학습"},{"id":16439,"term":"instinct","meaning":"본능","partOfSpeech":"n.","example":"Her first instinct was to run when she heard the loud noise.","exampleTranslation":"그녀는 큰 소리를 듣자 본능적으로 도망치려 했습니다.","level":17,"category":"빈도 학습"},{"id":16440,"term":"institute","meaning":"(제도 등을) 도입하다; 제정하다","partOfSpeech":"v.","example":"The school decided to institute a stricter dress code this semester.","exampleTranslation":"그 학교는 이번 학기에 더 엄격한 복장 규정을 도입하기로 했습니다.","level":17,"category":"빈도 학습"},{"id":16441,"term":"interact","meaning":"상호작용하다; 교류하다","partOfSpeech":"v.","example":"Employees are encouraged to interact with customers in a friendly way.","exampleTranslation":"직원들은 고객과 친근하게 교류하도록 권장됩니다.","level":17,"category":"빈도 학습"},{"id":16442,"term":"interfere","meaning":"간섭하다; 방해하다","partOfSpeech":"v.","example":"Parents should try not to interfere too much in their adult children's lives.","exampleTranslation":"부모는 성인이 된 자녀의 삶에 너무 많이 간섭하지 않으려고 노력해야 합니다.","level":17,"category":"빈도 학습"},{"id":16443,"term":"intervene","meaning":"개입하다; 중재하다","partOfSpeech":"v.","example":"The teacher had to intervene before the argument turned into a fight.","exampleTranslation":"선생님은 말다툼이 몸싸움으로 번지기 전에 개입해야 했습니다.","level":17,"category":"빈도 학습"},{"id":16444,"term":"intimate","meaning":"친밀한","partOfSpeech":"adj.","example":"The two old friends had an intimate conversation over coffee.","exampleTranslation":"그 오랜 친구 두 명은 커피를 마시며 친밀한 대화를 나눴습니다.","level":17,"category":"빈도 학습"},{"id":16445,"term":"invasion","meaning":"침략","partOfSpeech":"n.","example":"Historians still debate the causes of the invasion.","exampleTranslation":"역사학자들은 여전히 그 침략의 원인에 대해 논쟁합니다.","level":17,"category":"빈도 학습"},{"id":16446,"term":"irony","meaning":"아이러니; 반어법","partOfSpeech":"n.","example":"There is a certain irony in a fire station burning down.","exampleTranslation":"소방서가 불에 타버렸다는 사실에는 어떤 아이러니가 있습니다.","level":17,"category":"빈도 학습"},{"id":16447,"term":"jet","meaning":"(비행기로) 훌쩍 떠나다","partOfSpeech":"v.","example":"They plan to jet off to Hawaii for their honeymoon next month.","exampleTranslation":"그들은 다음 달 신혼여행으로 하와이로 훌쩍 떠날 계획입니다.","level":17,"category":"빈도 학습"},{"id":16448,"term":"legend","meaning":"전설","partOfSpeech":"n.","example":"According to legend, a dragon once lived in these mountains.","exampleTranslation":"전설에 따르면 옛날 이 산에는 용이 살았다고 합니다.","level":17,"category":"빈도 학습"},{"id":16449,"term":"legislate","meaning":"입법하다; 법률을 제정하다","partOfSpeech":"v.","example":"Governments cannot legislate against every possible risk in life.","exampleTranslation":"정부가 삶의 모든 위험 요소에 대해 법을 만들 수는 없습니다.","level":17,"category":"빈도 학습"},{"id":16450,"term":"legitimate","meaning":"합법적인; 정당한","partOfSpeech":"adj.","example":"The company has a legitimate reason for raising its prices.","exampleTranslation":"그 회사는 가격을 올릴 정당한 이유가 있습니다.","level":17,"category":"빈도 학습"},{"id":16451,"term":"liable","meaning":"책임이 있는; ~하기 쉬운","partOfSpeech":"adj.","example":"The driver was found liable for the accident.","exampleTranslation":"그 운전자는 사고에 대한 책임이 있다고 판정되었습니다.","level":17,"category":"빈도 학습"},{"id":16452,"term":"liberate","meaning":"해방시키다; 자유롭게 하다","partOfSpeech":"v.","example":"The soldiers helped liberate the city from enemy control.","exampleTranslation":"군인들은 그 도시를 적의 지배에서 해방시키는 데 힘을 보탰습니다.","level":17,"category":"빈도 학습"},{"id":16453,"term":"liberty","meaning":"자유","partOfSpeech":"n.","example":"Citizens fought hard to protect their liberty.","exampleTranslation":"시민들은 자신들의 자유를 지키기 위해 힘껏 싸웠습니다.","level":17,"category":"빈도 학습"},{"id":16454,"term":"literal","meaning":"문자 그대로의","partOfSpeech":"adj.","example":"Don't take his joke in a literal sense.","exampleTranslation":"그의 농담을 문자 그대로 받아들이지 마세요.","level":17,"category":"빈도 학습"},{"id":16455,"term":"lobby","meaning":"로비하다; 압력을 넣다","partOfSpeech":"v.","example":"Several groups lobby the government to lower taxes.","exampleTranslation":"여러 단체가 세금을 낮추도록 정부에 로비를 합니다.","level":17,"category":"빈도 학습"},{"id":16456,"term":"lodge","meaning":"(불만 등을) 제기하다; 묵다","partOfSpeech":"v.","example":"She decided to lodge a complaint with the manager.","exampleTranslation":"그녀는 매니저에게 불만을 제기하기로 결정했습니다.","level":17,"category":"빈도 학습"},{"id":16457,"term":"loyal","meaning":"충실한; 충성스러운","partOfSpeech":"adj.","example":"The dog remained loyal to its owner for many years.","exampleTranslation":"그 개는 오랫동안 주인에게 충실했습니다.","level":17,"category":"빈도 학습"},{"id":16458,"term":"magnet","meaning":"자석","partOfSpeech":"n.","example":"The magnet on the fridge holds notes in place.","exampleTranslation":"냉장고에 붙은 자석이 메모를 고정해 줍니다.","level":17,"category":"빈도 학습"},{"id":16459,"term":"manifest","meaning":"(감정·질병 등이) 나타나다; 드러나다","partOfSpeech":"v.","example":"Stress can manifest itself as headaches or fatigue.","exampleTranslation":"스트레스는 두통이나 피로로 나타날 수 있습니다.","level":17,"category":"빈도 학습"},{"id":16460,"term":"manipulate","meaning":"조종하다; 조작하다","partOfSpeech":"v.","example":"He tried to manipulate the data to support his theory.","exampleTranslation":"그는 자신의 이론을 뒷받침하려고 데이터를 조작하려 했습니다.","level":17,"category":"빈도 학습"},{"id":16461,"term":"manual","meaning":"수동의; 육체노동의","partOfSpeech":"adj.","example":"The factory replaced manual labor with automated machines.","exampleTranslation":"그 공장은 수동 작업을 자동화된 기계로 대체했습니다.","level":17,"category":"빈도 학습"},{"id":16462,"term":"marine","meaning":"해양의; 바다의","partOfSpeech":"adj.","example":"Scientists study marine life along the coral reef.","exampleTranslation":"과학자들은 산호초를 따라 해양 생물을 연구합니다.","level":17,"category":"빈도 학습"},{"id":16463,"term":"poison","meaning":"독을 넣다; 오염시키다","partOfSpeech":"v.","example":"Someone tried to poison the water supply.","exampleTranslation":"누군가가 상수도에 독을 넣으려 했습니다.","level":17,"category":"빈도 학습"},{"id":16464,"term":"pole","meaning":"막대; 극(極)","partOfSpeech":"n.","example":"The flag was raised on a tall pole.","exampleTranslation":"깃발이 높은 막대 위로 올려졌습니다.","level":17,"category":"빈도 학습"},{"id":16465,"term":"polish","meaning":"닦다; 광을 내다","partOfSpeech":"v.","example":"She likes to polish her shoes every Sunday morning.","exampleTranslation":"그녀는 일요일 아침마다 구두를 닦는 것을 좋아합니다.","level":17,"category":"빈도 학습"},{"id":16466,"term":"polite","meaning":"예의 바른; 공손한","partOfSpeech":"adj.","example":"It's polite to say thank you when someone helps you.","exampleTranslation":"누군가 도와주면 고맙다고 말하는 것이 예의 바른 행동입니다.","level":17,"category":"빈도 학습"},{"id":16467,"term":"pollute","meaning":"오염시키다","partOfSpeech":"v.","example":"Factories should not pollute the river with chemical waste.","exampleTranslation":"공장들은 화학 폐기물로 강을 오염시키면 안 됩니다.","level":17,"category":"빈도 학습"},{"id":16468,"term":"presume","meaning":"추정하다; 짐작하다","partOfSpeech":"v.","example":"I presume you already know about the schedule change.","exampleTranslation":"저는 당신이 일정 변경에 대해 이미 알고 있을 거라고 짐작합니다.","level":17,"category":"빈도 학습"},{"id":16469,"term":"privacy","meaning":"사생활; 프라이버시","partOfSpeech":"n.","example":"He values his privacy and rarely posts online.","exampleTranslation":"그는 자신의 사생활을 소중히 여겨서 온라인에 거의 게시하지 않습니다.","level":17,"category":"빈도 학습"},{"id":16470,"term":"pronounce","meaning":"발음하다; 선언하다","partOfSpeech":"v.","example":"Many students find it hard to pronounce this word correctly.","exampleTranslation":"많은 학생들이 이 단어를 정확히 발음하는 것을 어려워합니다.","level":17,"category":"빈도 학습"},{"id":16471,"term":"pudding","meaning":"푸딩","partOfSpeech":"n.","example":"We had chocolate pudding for dessert.","exampleTranslation":"우리는 디저트로 초콜릿 푸딩을 먹었습니다.","level":17,"category":"빈도 학습"},{"id":16472,"term":"while","meaning":"~하는 반면; ~하는 동안","partOfSpeech":"conj.","example":"While John loves coffee, his sister prefers tea.","exampleTranslation":"존은 커피를 좋아하는 반면, 그의 여동생은 차를 더 좋아합니다.","level":17,"category":"빈도 학습"},{"id":16473,"term":"who","meaning":"누구; (관계대명사) ~하는 사람","partOfSpeech":"pron.","example":"Who left this umbrella on the table?","exampleTranslation":"누가 이 우산을 탁자 위에 놓고 갔나요?","level":17,"category":"빈도 학습"},{"id":16474,"term":"mechanic","meaning":"정비공; 기술자","partOfSpeech":"n.","example":"The mechanic fixed my car's engine in one afternoon.","exampleTranslation":"그 정비공은 하루 오후 만에 제 차 엔진을 고쳤습니다.","level":18,"category":"빈도 학습"},{"id":16475,"term":"migrate","meaning":"이주하다; (동물이) 이동하다","partOfSpeech":"v.","example":"Many birds migrate south before winter arrives.","exampleTranslation":"많은 새들이 겨울이 오기 전에 남쪽으로 이동합니다.","level":18,"category":"빈도 학습"},{"id":16476,"term":"miner","meaning":"광부","partOfSpeech":"n.","example":"The miner spent eight hours underground every day.","exampleTranslation":"그 광부는 매일 여덟 시간을 지하에서 보냈습니다.","level":18,"category":"빈도 학습"},{"id":16477,"term":"ministry","meaning":"(정부의) 부처; 성직","partOfSpeech":"n.","example":"The Ministry of Education announced new school guidelines.","exampleTranslation":"교육부는 새로운 학교 지침을 발표했습니다.","level":18,"category":"빈도 학습"},{"id":16478,"term":"missile","meaning":"미사일","partOfSpeech":"n.","example":"The military tested a new missile in the desert.","exampleTranslation":"군은 사막에서 새 미사일을 시험했습니다.","level":18,"category":"빈도 학습"},{"id":16479,"term":"modest","meaning":"겸손한; 적당한","partOfSpeech":"adj.","example":"Despite his success, he remained modest about his achievements.","exampleTranslation":"성공했음에도 불구하고 그는 자신의 성과에 대해 겸손했습니다.","level":18,"category":"빈도 학습"},{"id":16480,"term":"molecule","meaning":"분자","partOfSpeech":"n.","example":"A water molecule is made of two hydrogen atoms and one oxygen atom.","exampleTranslation":"물 분자는 수소 원자 두 개와 산소 원자 한 개로 이루어져 있습니다.","level":18,"category":"빈도 학습"},{"id":16481,"term":"monster","meaning":"괴물","partOfSpeech":"n.","example":"The little boy was scared of the monster in his dream.","exampleTranslation":"그 어린 소년은 꿈에 나온 괴물을 무서워했습니다.","level":18,"category":"빈도 학습"},{"id":16482,"term":"mortal","meaning":"죽을 운명의; 치명적인","partOfSpeech":"adj.","example":"Even great heroes are mortal in the end.","exampleTranslation":"위대한 영웅들도 결국은 죽을 운명입니다.","level":18,"category":"빈도 학습"},{"id":16483,"term":"motive","meaning":"동기","partOfSpeech":"n.","example":"Police could not find a clear motive for the crime.","exampleTranslation":"경찰은 그 범죄의 명확한 동기를 찾지 못했습니다.","level":18,"category":"빈도 학습"},{"id":16484,"term":"myth","meaning":"신화; 근거 없는 통념","partOfSpeech":"n.","example":"It's a common myth that we only use ten percent of our brain.","exampleTranslation":"우리가 뇌의 10퍼센트만 사용한다는 것은 흔한 근거 없는 통념입니다.","level":18,"category":"빈도 학습"},{"id":16485,"term":"naked","meaning":"벌거벗은; 있는 그대로의","partOfSpeech":"adj.","example":"You could see the stars clearly with the naked eye.","exampleTranslation":"맨눈으로도 별들이 또렷하게 보였습니다.","level":18,"category":"빈도 학습"},{"id":16486,"term":"narrate","meaning":"이야기하다; 내레이션을 하다","partOfSpeech":"v.","example":"A famous actor was chosen to narrate the documentary.","exampleTranslation":"한 유명 배우가 그 다큐멘터리의 내레이션을 맡기로 선정되었습니다.","level":18,"category":"빈도 학습"},{"id":16487,"term":"neutral","meaning":"중립적인","partOfSpeech":"adj.","example":"Switzerland remained neutral during the war.","exampleTranslation":"스위스는 전쟁 중에 중립을 지켰습니다.","level":18,"category":"빈도 학습"},{"id":16488,"term":"nod","meaning":"고개를 끄덕이다","partOfSpeech":"v.","example":"She began to nod as she agreed with his plan.","exampleTranslation":"그녀는 그의 계획에 동의하면서 고개를 끄덕이기 시작했습니다.","level":18,"category":"빈도 학습"},{"id":16489,"term":"nominate","meaning":"지명하다; 후보로 추천하다","partOfSpeech":"v.","example":"The committee will nominate three candidates for the award.","exampleTranslation":"위원회는 그 상의 후보로 세 명을 지명할 것입니다.","level":18,"category":"빈도 학습"},{"id":16490,"term":"occupation","meaning":"직업; 점령","partOfSpeech":"n.","example":"Please state your name, age, and occupation on the form.","exampleTranslation":"양식에 이름, 나이, 직업을 적어 주세요.","level":18,"category":"빈도 학습"},{"id":16491,"term":"offend","meaning":"기분 상하게 하다; 불쾌하게 하다","partOfSpeech":"v.","example":"I didn't mean to offend you with my comment.","exampleTranslation":"제 말로 당신 기분을 상하게 할 의도는 없었습니다.","level":18,"category":"빈도 학습"},{"id":16492,"term":"oral","meaning":"구두의; 입의","partOfSpeech":"adj.","example":"Students must pass an oral exam as well as a written one.","exampleTranslation":"학생들은 필기시험뿐 아니라 구두시험도 통과해야 합니다.","level":18,"category":"빈도 학습"},{"id":16493,"term":"organ","meaning":"장기(신체 기관); 오르간","partOfSpeech":"n.","example":"The heart is an organ that pumps blood through the body.","exampleTranslation":"심장은 온몸으로 피를 보내는 장기입니다.","level":18,"category":"빈도 학습"},{"id":16494,"term":"outrage","meaning":"격분하게 하다","partOfSpeech":"v.","example":"The unfair verdict continued to outrage the public.","exampleTranslation":"그 불공정한 판결은 계속해서 대중을 격분하게 했습니다.","level":18,"category":"빈도 학습"},{"id":16495,"term":"overwhelm","meaning":"압도하다; 감당 못하게 하다","partOfSpeech":"v.","example":"The amount of homework began to overwhelm her.","exampleTranslation":"숙제의 양이 그녀를 감당 못하게 만들기 시작했습니다.","level":18,"category":"빈도 학습"},{"id":16496,"term":"pad","meaning":"(속을) 채우다; 완충재를 대다","partOfSpeech":"v.","example":"Please pad the box with foam before shipping it.","exampleTranslation":"배송하기 전에 상자를 폼으로 채워 주세요.","level":18,"category":"빈도 학습"},{"id":16497,"term":"palace","meaning":"궁전","partOfSpeech":"n.","example":"Tourists lined up to visit the royal palace.","exampleTranslation":"관광객들은 그 왕궁을 방문하려고 줄을 섰습니다.","level":18,"category":"빈도 학습"},{"id":16498,"term":"punch","meaning":"주먹으로 치다","partOfSpeech":"v.","example":"He tried to punch the bag as hard as he could.","exampleTranslation":"그는 있는 힘껏 샌드백을 치려고 했습니다.","level":18,"category":"빈도 학습"},{"id":16499,"term":"punish","meaning":"처벌하다; 벌주다","partOfSpeech":"v.","example":"The teacher decided to punish the students who cheated.","exampleTranslation":"선생님은 부정행위를 한 학생들을 처벌하기로 결정했습니다.","level":18,"category":"빈도 학습"},{"id":16500,"term":"pup","meaning":"새끼 강아지","partOfSpeech":"n.","example":"The pup followed its mother everywhere in the yard.","exampleTranslation":"그 새끼 강아지는 마당에서 어미를 졸졸 따라다녔습니다.","level":18,"category":"빈도 학습"},{"id":16501,"term":"purple","meaning":"보라색의","partOfSpeech":"adj.","example":"She painted her bedroom walls a soft purple color.","exampleTranslation":"그녀는 침실 벽을 부드러운 보라색으로 칠했습니다.","level":18,"category":"빈도 학습"},{"id":16502,"term":"quit","meaning":"그만두다; 포기하다","partOfSpeech":"v.","example":"He decided to quit his job and travel the world.","exampleTranslation":"그는 직장을 그만두고 세계 여행을 떠나기로 결심했습니다.","level":18,"category":"빈도 학습"},{"id":16503,"term":"ray","meaning":"광선; 빛줄기","partOfSpeech":"n.","example":"A ray of sunlight came through the window.","exampleTranslation":"한 줄기 햇빛이 창문을 통해 들어왔습니다.","level":18,"category":"빈도 학습"},{"id":16504,"term":"refrigerator","meaning":"냉장고","partOfSpeech":"n.","example":"Please put the milk back in the refrigerator.","exampleTranslation":"우유는 다시 냉장고에 넣어 주세요.","level":18,"category":"빈도 학습"},{"id":16505,"term":"ridiculous","meaning":"터무니없는; 우스꽝스러운","partOfSpeech":"adj.","example":"It's ridiculous to expect me to finish this in one hour.","exampleTranslation":"이걸 한 시간 안에 끝내라는 건 터무니없는 요구입니다.","level":18,"category":"빈도 학습"},{"id":16506,"term":"rip","meaning":"찢다","partOfSpeech":"v.","example":"Be careful not to rip the paper while you fold it.","exampleTranslation":"접을 때 종이를 찢지 않도록 조심하세요.","level":18,"category":"빈도 학습"},{"id":16507,"term":"roar","meaning":"으르렁거리다; 굉음을 내다","partOfSpeech":"v.","example":"The lion began to roar as the visitors approached.","exampleTranslation":"관람객들이 다가오자 사자가 으르렁거리기 시작했습니다.","level":18,"category":"빈도 학습"},{"id":16508,"term":"rob","meaning":"강탈하다; 털다","partOfSpeech":"v.","example":"Two men tried to rob the bank on Friday morning.","exampleTranslation":"두 남자가 금요일 아침 은행을 털려고 했습니다.","level":18,"category":"빈도 학습"},{"id":16509,"term":"rope","meaning":"밧줄로 막다; 묶다","partOfSpeech":"v.","example":"Workers rope off the area to keep visitors safe.","exampleTranslation":"인부들은 방문객의 안전을 위해 그 구역을 밧줄로 막습니다.","level":18,"category":"빈도 학습"},{"id":16510,"term":"rot","meaning":"썩다; 부패하다","partOfSpeech":"v.","example":"Fruit will rot quickly if you leave it in the sun.","exampleTranslation":"과일을 햇볕에 두면 빨리 썩습니다.","level":18,"category":"빈도 학습"},{"id":16511,"term":"why","meaning":"왜; 이유","partOfSpeech":"adv.","example":"Why did you leave the party so early last night?","exampleTranslation":"어젯밤 파티를 그렇게 일찍 떠난 이유가 뭐예요?","level":18,"category":"빈도 학습"},{"id":16512,"term":"palm","meaning":"손바닥; 야자수","partOfSpeech":"n.","example":"She held the small bird gently in her palm.","exampleTranslation":"그녀는 작은 새를 손바닥 위에 조심스럽게 올려놓았습니다.","level":19,"category":"빈도 학습"},{"id":16513,"term":"parish","meaning":"교구","partOfSpeech":"n.","example":"The new priest was welcomed warmly by the parish.","exampleTranslation":"새로 온 신부는 교구 신자들에게 따뜻한 환영을 받았습니다.","level":19,"category":"빈도 학습"},{"id":16514,"term":"parliament","meaning":"의회; 국회","partOfSpeech":"n.","example":"Parliament passed the new law after a long debate.","exampleTranslation":"의회는 오랜 논쟁 끝에 새 법을 통과시켰습니다.","level":19,"category":"빈도 학습"},{"id":16515,"term":"pave","meaning":"포장하다; 길을 닦다","partOfSpeech":"v.","example":"The city plans to pave the dirt road next spring.","exampleTranslation":"시는 내년 봄에 그 비포장 도로를 포장할 계획입니다.","level":19,"category":"빈도 학습"},{"id":16516,"term":"peasant","meaning":"농민; 소작농","partOfSpeech":"n.","example":"In the old story, a poor peasant becomes king.","exampleTranslation":"그 옛날이야기에서 가난한 농민이 왕이 됩니다.","level":19,"category":"빈도 학습"},{"id":16517,"term":"pepper","meaning":"후추; 고추","partOfSpeech":"n.","example":"She added a pinch of pepper to the soup.","exampleTranslation":"그녀는 수프에 후추를 한 꼬집 넣었습니다.","level":19,"category":"빈도 학습"},{"id":16518,"term":"persist","meaning":"지속되다; 끈질기게 계속하다","partOfSpeech":"v.","example":"These symptoms sometimes persist for weeks in certain patients.","exampleTranslation":"이 증상들은 일부 환자에게서 몇 주 동안 지속되기도 합니다.","level":19,"category":"빈도 학습"},{"id":16519,"term":"petrol","meaning":"휘발유","partOfSpeech":"n.","example":"We stopped at the station to fill up on petrol.","exampleTranslation":"우리는 휘발유를 채우려고 주유소에 멈췄습니다.","level":19,"category":"빈도 학습"},{"id":16520,"term":"pit","meaning":"맞붙게 하다; 대결시키다","partOfSpeech":"v.","example":"The final match will pit the two best teams against each other.","exampleTranslation":"결승전은 최고의 두 팀을 서로 맞붙게 할 것입니다.","level":19,"category":"빈도 학습"},{"id":16521,"term":"powder","meaning":"가루; 분말","partOfSpeech":"n.","example":"Mix the powder with warm water before drinking it.","exampleTranslation":"마시기 전에 가루를 따뜻한 물에 섞으세요.","level":19,"category":"빈도 학습"},{"id":16522,"term":"practitioner","meaning":"개업의; 실무자","partOfSpeech":"n.","example":"She works as a general practitioner at the local clinic.","exampleTranslation":"그녀는 지역 병원에서 일반의로 일하고 있습니다.","level":19,"category":"빈도 학습"},{"id":16523,"term":"precede","meaning":"앞서다; 선행하다","partOfSpeech":"v.","example":"A short introduction will precede the main presentation.","exampleTranslation":"짧은 소개가 본 발표에 앞서 진행될 것입니다.","level":19,"category":"빈도 학습"},{"id":16524,"term":"priest","meaning":"사제; 신부","partOfSpeech":"n.","example":"The priest gave a moving speech at the wedding.","exampleTranslation":"그 신부는 결혼식에서 감동적인 말씀을 전했습니다.","level":19,"category":"빈도 학습"},{"id":16525,"term":"probe","meaning":"캐묻다; 조사하다","partOfSpeech":"v.","example":"Reporters began to probe deeper into the scandal.","exampleTranslation":"기자들은 그 스캔들을 더 깊이 캐묻기 시작했습니다.","level":19,"category":"빈도 학습"},{"id":16526,"term":"profound","meaning":"심오한; 깊은","partOfSpeech":"adj.","example":"The book had a profound effect on how she saw life.","exampleTranslation":"그 책은 그녀가 삶을 바라보는 방식에 심오한 영향을 미쳤습니다.","level":19,"category":"빈도 학습"},{"id":16527,"term":"prohibit","meaning":"금지하다","partOfSpeech":"v.","example":"This sign clearly states that the rules prohibit smoking indoors.","exampleTranslation":"이 표지판은 규칙상 실내 흡연을 금지한다고 분명히 밝히고 있습니다.","level":19,"category":"빈도 학습"},{"id":16528,"term":"prominent","meaning":"두드러진; 저명한","partOfSpeech":"adj.","example":"A prominent scientist will give the opening speech.","exampleTranslation":"한 저명한 과학자가 개회사를 할 것입니다.","level":19,"category":"빈도 학습"},{"id":16529,"term":"prosecute","meaning":"기소하다","partOfSpeech":"v.","example":"The government decided to prosecute the company for fraud.","exampleTranslation":"정부는 그 회사를 사기 혐의로 기소하기로 결정했습니다.","level":19,"category":"빈도 학습"},{"id":16530,"term":"prosper","meaning":"번영하다","partOfSpeech":"v.","example":"The small business began to prosper after the new manager arrived.","exampleTranslation":"그 작은 사업체는 새 매니저가 온 뒤로 번영하기 시작했습니다.","level":19,"category":"빈도 학습"},{"id":16531,"term":"provoke","meaning":"자극하다; 유발하다","partOfSpeech":"v.","example":"His comment was meant to provoke a reaction from the crowd.","exampleTranslation":"그의 발언은 군중의 반응을 자극하려는 의도였습니다.","level":19,"category":"빈도 학습"},{"id":16532,"term":"psychiatry","meaning":"정신의학","partOfSpeech":"n.","example":"She chose to specialize in psychiatry after medical school.","exampleTranslation":"그녀는 의대를 졸업한 뒤 정신의학을 전공하기로 했습니다.","level":19,"category":"빈도 학습"},{"id":16533,"term":"psychology","meaning":"심리학","partOfSpeech":"n.","example":"He studies psychology to understand why people behave the way they do.","exampleTranslation":"그는 사람들이 왜 그렇게 행동하는지 이해하려고 심리학을 공부합니다.","level":19,"category":"빈도 학습"},{"id":16534,"term":"publish","meaning":"출판하다; 게재하다","partOfSpeech":"v.","example":"The author plans to publish her next novel this fall.","exampleTranslation":"그 작가는 올가을에 다음 소설을 출판할 계획입니다.","level":19,"category":"빈도 학습"},{"id":16535,"term":"puzzle","meaning":"어리둥절하게 하다; 혼란스럽게 하다","partOfSpeech":"v.","example":"The strange results continued to puzzle the researchers.","exampleTranslation":"그 이상한 결과는 계속해서 연구자들을 어리둥절하게 만들었습니다.","level":19,"category":"빈도 학습"},{"id":16536,"term":"radiate","meaning":"발산하다; 뿜어져 나오다","partOfSpeech":"v.","example":"Warmth began to radiate from the fireplace across the room.","exampleTranslation":"벽난로에서 나온 온기가 방 전체로 퍼져 나가기 시작했습니다.","level":19,"category":"빈도 학습"},{"id":16537,"term":"rage","meaning":"격노하다; 맹위를 떨치다","partOfSpeech":"v.","example":"The storm continued to rage throughout the night.","exampleTranslation":"그 폭풍은 밤새 맹위를 떨쳤습니다.","level":19,"category":"빈도 학습"},{"id":16538,"term":"raid","meaning":"급습하다; 단속하다","partOfSpeech":"v.","example":"Police plan to raid the warehouse at dawn.","exampleTranslation":"경찰은 새벽에 그 창고를 급습할 계획입니다.","level":19,"category":"빈도 학습"},{"id":16539,"term":"rub","meaning":"문지르다","partOfSpeech":"v.","example":"She began to rub her eyes after staring at the screen for hours.","exampleTranslation":"그녀는 몇 시간 동안 화면을 본 뒤 눈을 비비기 시작했습니다.","level":19,"category":"빈도 학습"},{"id":16540,"term":"rude","meaning":"무례한","partOfSpeech":"adj.","example":"It was rude of him to interrupt her while she was speaking.","exampleTranslation":"그녀가 말하는 도중에 끼어든 것은 무례한 행동이었습니다.","level":19,"category":"빈도 학습"},{"id":16541,"term":"saint","meaning":"성인(聖人)","partOfSpeech":"n.","example":"The church was named after a famous saint.","exampleTranslation":"그 교회는 유명한 성인의 이름을 따서 지어졌습니다.","level":19,"category":"빈도 학습"},{"id":16542,"term":"sandwich","meaning":"샌드위치","partOfSpeech":"n.","example":"I made a turkey sandwich for lunch.","exampleTranslation":"저는 점심으로 칠면조 샌드위치를 만들었습니다.","level":19,"category":"빈도 학습"},{"id":16543,"term":"sauce","meaning":"소스","partOfSpeech":"n.","example":"The chef added extra sauce to the pasta.","exampleTranslation":"요리사는 파스타에 소스를 더 넣었습니다.","level":19,"category":"빈도 학습"},{"id":16544,"term":"sausage","meaning":"소시지","partOfSpeech":"n.","example":"We grilled sausage and vegetables for dinner.","exampleTranslation":"우리는 저녁으로 소시지와 채소를 구웠습니다.","level":19,"category":"빈도 학습"},{"id":16545,"term":"scratch","meaning":"긁다","partOfSpeech":"v.","example":"The cat tried to scratch the sofa with its claws.","exampleTranslation":"그 고양이는 발톱으로 소파를 긁으려 했습니다.","level":19,"category":"빈도 학습"},{"id":16546,"term":"september","meaning":"9월","partOfSpeech":"n.","example":"School usually starts in September in the United States.","exampleTranslation":"미국에서는 보통 9월에 학교가 시작됩니다.","level":19,"category":"빈도 학습"},{"id":16547,"term":"sew","meaning":"바느질하다; 꿰매다","partOfSpeech":"v.","example":"My grandmother taught me how to sew a button back on.","exampleTranslation":"할머니는 저에게 단추를 다시 꿰매는 법을 가르쳐 주셨습니다.","level":19,"category":"빈도 학습"},{"id":16548,"term":"shame","meaning":"부끄럽게 하다; 망신을 주다","partOfSpeech":"v.","example":"Public criticism was used to shame the company into changing its policy.","exampleTranslation":"대중의 비판은 그 회사가 정책을 바꾸도록 망신을 주는 데 사용되었습니다.","level":19,"category":"빈도 학습"},{"id":16549,"term":"with","meaning":"~와 함께; ~을 가지고","partOfSpeech":"prep.","example":"Do you want to come with me to the concert tonight?","exampleTranslation":"오늘 밤 콘서트에 저와 함께 갈래요?","level":19,"category":"빈도 학습"},{"id":16550,"term":"rally","meaning":"결집하다; 모으다","partOfSpeech":"v.","example":"The coach tried to rally the team after they fell behind.","exampleTranslation":"코치는 팀이 뒤처지자 선수들을 다시 결집시키려 했습니다.","level":20,"category":"빈도 학습"},{"id":16551,"term":"rational","meaning":"이성적인; 합리적인","partOfSpeech":"adj.","example":"Try to stay rational and not let your emotions control the decision.","exampleTranslation":"감정이 결정을 좌우하게 하지 말고 이성적으로 판단하려고 노력하세요.","level":20,"category":"빈도 학습"},{"id":16552,"term":"rebel","meaning":"반항하다; 반란을 일으키다","partOfSpeech":"v.","example":"Teenagers sometimes rebel against their parents' rules.","exampleTranslation":"십 대들은 때때로 부모님의 규칙에 반항합니다.","level":20,"category":"빈도 학습"},{"id":16553,"term":"receiver","meaning":"수화기; 수신자","partOfSpeech":"n.","example":"She picked up the receiver as soon as the phone rang.","exampleTranslation":"그녀는 전화벨이 울리자마자 수화기를 들었습니다.","level":20,"category":"빈도 학습"},{"id":16554,"term":"reception","meaning":"환영회; 접수처","partOfSpeech":"n.","example":"Please check in at the reception desk when you arrive.","exampleTranslation":"도착하시면 접수처에서 체크인해 주세요.","level":20,"category":"빈도 학습"},{"id":16555,"term":"recession","meaning":"경기 침체; 불황","partOfSpeech":"n.","example":"Many people lost their jobs during the last recession.","exampleTranslation":"지난 경기 침체 동안 많은 사람들이 일자리를 잃었습니다.","level":20,"category":"빈도 학습"},{"id":16556,"term":"refuge","meaning":"피난처; 대피","partOfSpeech":"n.","example":"The villagers took refuge in the mountains during the flood.","exampleTranslation":"마을 사람들은 홍수가 나자 산으로 피신했습니다.","level":20,"category":"빈도 학습"},{"id":16557,"term":"regime","meaning":"정권; 체제","partOfSpeech":"n.","example":"The new regime promised major reforms within its first year.","exampleTranslation":"새 정권은 집권 첫해 안에 대대적인 개혁을 약속했습니다.","level":20,"category":"빈도 학습"},{"id":16558,"term":"reinforce","meaning":"강화하다; 보강하다","partOfSpeech":"v.","example":"Workers added steel bars to reinforce the old bridge.","exampleTranslation":"인부들은 오래된 다리를 보강하기 위해 철근을 추가했습니다.","level":20,"category":"빈도 학습"},{"id":16559,"term":"relieve","meaning":"완화하다; 덜어 주다","partOfSpeech":"v.","example":"This medicine should relieve your headache within an hour.","exampleTranslation":"이 약은 한 시간 안에 두통을 완화해 줄 것입니다.","level":20,"category":"빈도 학습"},{"id":16560,"term":"reluctant","meaning":"마지못한; 꺼리는","partOfSpeech":"adj.","example":"He was reluctant to share his true feelings with anyone.","exampleTranslation":"그는 자신의 진짜 감정을 누구에게도 털어놓기를 꺼렸습니다.","level":20,"category":"빈도 학습"},{"id":16561,"term":"remedy","meaning":"바로잡다; 개선하다","partOfSpeech":"v.","example":"The company took quick steps to remedy the problem.","exampleTranslation":"그 회사는 문제를 바로잡기 위해 신속한 조치를 취했습니다.","level":20,"category":"빈도 학습"},{"id":16562,"term":"render","meaning":"(어떤 상태가 되게) 만들다; 제공하다","partOfSpeech":"v.","example":"The heavy snow began to render the roads impassable.","exampleTranslation":"폭설은 도로를 지나갈 수 없게 만들기 시작했습니다.","level":20,"category":"빈도 학습"},{"id":16563,"term":"reproduce","meaning":"복제하다; 번식하다","partOfSpeech":"v.","example":"Rabbits reproduce much faster than most other mammals.","exampleTranslation":"토끼는 대부분의 다른 포유류보다 훨씬 빨리 번식합니다.","level":20,"category":"빈도 학습"},{"id":16564,"term":"republic","meaning":"공화국","partOfSpeech":"n.","example":"The country became a republic after the revolution.","exampleTranslation":"그 나라는 혁명 이후 공화국이 되었습니다.","level":20,"category":"빈도 학습"},{"id":16565,"term":"resemble","meaning":"닮다; 비슷하다","partOfSpeech":"v.","example":"People say the twins closely resemble their mother.","exampleTranslation":"사람들은 그 쌍둥이가 어머니를 많이 닮았다고 말합니다.","level":20,"category":"빈도 학습"},{"id":16566,"term":"reside","meaning":"거주하다","partOfSpeech":"v.","example":"Most of the company's engineers reside in the same city as the office.","exampleTranslation":"그 회사 엔지니어 대부분은 사무실과 같은 도시에 거주합니다.","level":20,"category":"빈도 학습"},{"id":16567,"term":"respective","meaning":"각자의; 각각의","partOfSpeech":"adj.","example":"After the meeting, the members returned to their respective offices.","exampleTranslation":"회의가 끝난 뒤 회원들은 각자의 사무실로 돌아갔습니다.","level":20,"category":"빈도 학습"},{"id":16568,"term":"restrain","meaning":"억제하다; 제지하다","partOfSpeech":"v.","example":"Security guards had to restrain the angry customer.","exampleTranslation":"경비원들은 화가 난 그 손님을 제지해야 했습니다.","level":20,"category":"빈도 학습"},{"id":16569,"term":"retreat","meaning":"후퇴하다; 물러나다","partOfSpeech":"v.","example":"The soldiers were ordered to retreat when the battle turned against them.","exampleTranslation":"전세가 불리해지자 병사들은 후퇴하라는 명령을 받았습니다.","level":20,"category":"빈도 학습"},{"id":16570,"term":"revive","meaning":"되살리다; 소생시키다","partOfSpeech":"v.","example":"Doctors managed to revive the patient after several minutes.","exampleTranslation":"의사들은 몇 분 만에 그 환자를 소생시키는 데 성공했습니다.","level":20,"category":"빈도 학습"},{"id":16571,"term":"rhythm","meaning":"리듬; 박자","partOfSpeech":"n.","example":"The dancers moved perfectly in rhythm with the music.","exampleTranslation":"무용수들은 음악의 리듬에 완벽하게 맞춰 움직였습니다.","level":20,"category":"빈도 학습"},{"id":16572,"term":"ritual","meaning":"의식; 절차","partOfSpeech":"n.","example":"Drinking a cup of tea every morning became her daily ritual.","exampleTranslation":"매일 아침 차 한 잔을 마시는 것이 그녀의 일상 의식이 되었습니다.","level":20,"category":"빈도 학습"},{"id":16573,"term":"rumor","meaning":"소문","partOfSpeech":"n.","example":"A rumor spread quickly that the store was closing down.","exampleTranslation":"그 가게가 문을 닫는다는 소문이 빠르게 퍼졌습니다.","level":20,"category":"빈도 학습"},{"id":16574,"term":"shave","meaning":"면도하다","partOfSpeech":"v.","example":"He likes to shave every morning before work.","exampleTranslation":"그는 출근 전 매일 아침 면도하는 것을 좋아합니다.","level":20,"category":"빈도 학습"},{"id":16575,"term":"shed","meaning":"(허물·눈물 등을) 흘리다; 벗다","partOfSpeech":"v.","example":"Snakes shed their skin several times a year.","exampleTranslation":"뱀은 일 년에 여러 번 허물을 벗습니다.","level":20,"category":"빈도 학습"},{"id":16576,"term":"shiver","meaning":"(추위·두려움에) 떨다","partOfSpeech":"v.","example":"She began to shiver as soon as she stepped out into the cold.","exampleTranslation":"그녀는 추운 밖으로 나가자마자 떨기 시작했습니다.","level":20,"category":"빈도 학습"},{"id":16577,"term":"shove","meaning":"밀치다","partOfSpeech":"v.","example":"Don't shove the other passengers when the train doors open.","exampleTranslation":"기차 문이 열릴 때 다른 승객들을 밀치지 마세요.","level":20,"category":"빈도 학습"},{"id":16578,"term":"smash","meaning":"박살내다; 세게 부딪히다","partOfSpeech":"v.","example":"One more strong hit could smash the window.","exampleTranslation":"한 번 더 세게 치면 창문이 박살날 수도 있습니다.","level":20,"category":"빈도 학습"},{"id":16579,"term":"snake","meaning":"뱀","partOfSpeech":"n.","example":"A snake slid quietly through the tall grass.","exampleTranslation":"뱀 한 마리가 키 큰 풀 사이로 조용히 미끄러져 지나갔습니다.","level":20,"category":"빈도 학습"},{"id":16580,"term":"sock","meaning":"양말","partOfSpeech":"n.","example":"He couldn't find a matching sock in the drawer.","exampleTranslation":"그는 서랍에서 짝이 맞는 양말을 찾지 못했습니다.","level":20,"category":"빈도 학습"},{"id":16581,"term":"sore","meaning":"아픈; 쑤시는","partOfSpeech":"adj.","example":"My legs were sore after running the marathon.","exampleTranslation":"마라톤을 뛰고 나서 다리가 쑤셨습니다.","level":20,"category":"빈도 학습"},{"id":16582,"term":"spoil","meaning":"망치다; (음식이) 상하다","partOfSpeech":"v.","example":"Don't spoil the surprise by telling her too early.","exampleTranslation":"너무 일찍 말해서 깜짝 선물을 망치지 마세요.","level":20,"category":"빈도 학습"},{"id":16583,"term":"spray","meaning":"뿌리다; 분무하다","partOfSpeech":"v.","example":"She likes to spray a little perfume before leaving the house.","exampleTranslation":"그녀는 집을 나서기 전에 향수를 살짝 뿌리는 것을 좋아합니다.","level":20,"category":"빈도 학습"},{"id":16584,"term":"stairs","meaning":"계단","partOfSpeech":"n.","example":"He ran up the stairs two at a time.","exampleTranslation":"그는 계단을 한 번에 두 칸씩 뛰어 올라갔습니다.","level":20,"category":"빈도 학습"},{"id":16585,"term":"starve","meaning":"굶주리다; 굶어 죽다","partOfSpeech":"v.","example":"Thousands of people continued to starve during the long drought.","exampleTranslation":"긴 가뭄 동안 수천 명의 사람들이 계속 굶주렸습니다.","level":20,"category":"빈도 학습"},{"id":16586,"term":"steak","meaning":"스테이크","partOfSpeech":"n.","example":"He ordered a steak cooked medium rare.","exampleTranslation":"그는 미디엄 레어로 익힌 스테이크를 주문했습니다.","level":20,"category":"빈도 학습"},{"id":16587,"term":"yet","meaning":"아직; 그런데도","partOfSpeech":"adv.","example":"I haven't finished my homework yet, so I can't go outside.","exampleTranslation":"아직 숙제를 다 끝내지 못해서 밖에 나갈 수 없습니다.","level":20,"category":"빈도 학습"},{"id":16588,"term":"sacrifice","meaning":"희생하다; 바치다","partOfSpeech":"v.","example":"Many parents sacrifice their own free time for their children.","exampleTranslation":"많은 부모들이 자녀를 위해 자신의 자유 시간을 희생합니다.","level":21,"category":"빈도 학습"},{"id":16589,"term":"satellite","meaning":"위성","partOfSpeech":"n.","example":"The satellite orbits the Earth once every ninety minutes.","exampleTranslation":"그 위성은 90분마다 한 번씩 지구를 공전합니다.","level":21,"category":"빈도 학습"},{"id":16590,"term":"scandal","meaning":"스캔들; 추문","partOfSpeech":"n.","example":"The political scandal forced the minister to resign.","exampleTranslation":"그 정치 스캔들로 인해 장관은 사임할 수밖에 없었습니다.","level":21,"category":"빈도 학습"},{"id":16591,"term":"scatter","meaning":"흩어지다; 흩뿌리다","partOfSpeech":"v.","example":"The birds began to scatter as soon as the dog appeared.","exampleTranslation":"개가 나타나자마자 새들은 흩어지기 시작했습니다.","level":21,"category":"빈도 학습"},{"id":16592,"term":"sculpt","meaning":"조각하다","partOfSpeech":"v.","example":"The artist used clay to sculpt a small figure of a horse.","exampleTranslation":"그 예술가는 점토로 작은 말 조각상을 만들었습니다.","level":21,"category":"빈도 학습"},{"id":16593,"term":"seize","meaning":"붙잡다; 장악하다","partOfSpeech":"v.","example":"Customs officers moved in to seize the illegal shipment.","exampleTranslation":"세관원들은 불법 화물을 압수하기 위해 움직였습니다.","level":21,"category":"빈도 학습"},{"id":16594,"term":"senate","meaning":"상원","partOfSpeech":"n.","example":"The bill must still pass through the senate before it becomes law.","exampleTranslation":"그 법안은 법이 되기 전에 상원을 통과해야 합니다.","level":21,"category":"빈도 학습"},{"id":16595,"term":"sensible","meaning":"분별 있는; 합리적인","partOfSpeech":"adj.","example":"It would be more sensible to save some money each month.","exampleTranslation":"매달 돈을 조금씩 저축하는 것이 더 분별 있는 선택일 것입니다.","level":21,"category":"빈도 학습"},{"id":16596,"term":"shield","meaning":"보호하다; 막아 주다","partOfSpeech":"v.","example":"Parents often try to shield their children from bad news.","exampleTranslation":"부모들은 종종 나쁜 소식으로부터 자녀를 보호하려고 합니다.","level":21,"category":"빈도 학습"},{"id":16597,"term":"shortly","meaning":"곧; 얼마 안 되어","partOfSpeech":"adv.","example":"The doctor will see you shortly, so please take a seat.","exampleTranslation":"의사 선생님이 곧 진료하실 테니 잠시 앉아 계세요.","level":21,"category":"빈도 학습"},{"id":16598,"term":"shrug","meaning":"어깨를 으쓱하다","partOfSpeech":"v.","example":"When asked about the rumor, she would just shrug and say nothing.","exampleTranslation":"그 소문에 대해 물으면 그녀는 그냥 어깨를 으쓱하며 아무 말도 하지 않았습니다.","level":21,"category":"빈도 학습"},{"id":16599,"term":"silk","meaning":"비단; 실크","partOfSpeech":"n.","example":"The dress was made of pure silk imported from China.","exampleTranslation":"그 드레스는 중국에서 수입한 순수한 실크로 만들어졌습니다.","level":21,"category":"빈도 학습"},{"id":16600,"term":"simultaneous","meaning":"동시의; 동시에 일어나는","partOfSpeech":"adj.","example":"The company held simultaneous meetings in New York and Tokyo.","exampleTranslation":"회사는 뉴욕과 도쿄에서 동시에 회의를 열었습니다.","level":21,"category":"빈도 학습"},{"id":16601,"term":"sin","meaning":"죄; 죄악","partOfSpeech":"n.","example":"In the story, the old man confessed his sin to the priest.","exampleTranslation":"이야기에서 노인은 신부에게 자신의 죄를 고백했습니다.","level":21,"category":"빈도 학습"},{"id":16602,"term":"sole","meaning":"유일한","partOfSpeech":"adj.","example":"She was the sole survivor of the plane crash.","exampleTranslation":"그녀는 그 비행기 사고의 유일한 생존자였습니다.","level":21,"category":"빈도 학습"},{"id":16603,"term":"sophisticated","meaning":"정교한; 세련된","partOfSpeech":"adj.","example":"The new smartphone has a sophisticated camera system.","exampleTranslation":"그 새 스마트폰은 정교한 카메라 시스템을 갖추고 있습니다.","level":21,"category":"빈도 학습"},{"id":16604,"term":"sovereign","meaning":"주권을 가진; 독립적인","partOfSpeech":"adj.","example":"After the war, the country became a fully sovereign nation.","exampleTranslation":"전쟁 후 그 나라는 완전한 주권 국가가 되었습니다.","level":21,"category":"빈도 학습"},{"id":16605,"term":"speculate","meaning":"추측하다; 짐작하다","partOfSpeech":"v.","example":"Reporters began to speculate about the reason for the sudden resignation.","exampleTranslation":"기자들은 갑작스러운 사임 이유에 대해 추측하기 시작했습니다.","level":21,"category":"빈도 학습"},{"id":16606,"term":"spill","meaning":"쏟다; 흘리다","partOfSpeech":"v.","example":"Be careful not to spill your coffee on the keyboard.","exampleTranslation":"키보드에 커피를 쏟지 않도록 조심하세요.","level":21,"category":"빈도 학습"},{"id":16607,"term":"squeeze","meaning":"짜다; 꽉 쥐다","partOfSpeech":"v.","example":"She had to squeeze the lemon to get enough juice for the recipe.","exampleTranslation":"그녀는 요리법에 필요한 즙을 얻기 위해 레몬을 짜야 했습니다.","level":21,"category":"빈도 학습"},{"id":16608,"term":"statute","meaning":"법령; 법규","partOfSpeech":"n.","example":"The new statute requires all restaurants to display calorie information.","exampleTranslation":"새 법령은 모든 식당이 칼로리 정보를 표시하도록 요구합니다.","level":21,"category":"빈도 학습"},{"id":16609,"term":"steam","meaning":"증기; 김","partOfSpeech":"n.","example":"Steam rose from the hot cup of tea on the table.","exampleTranslation":"탁자 위 뜨거운 찻잔에서 김이 피어올랐습니다.","level":21,"category":"빈도 학습"},{"id":16610,"term":"stiff","meaning":"뻣뻣한; 뻐근한","partOfSpeech":"adj.","example":"My neck feels stiff after sleeping in a strange position.","exampleTranslation":"이상한 자세로 잔 후 목이 뻐근합니다.","level":21,"category":"빈도 학습"},{"id":16611,"term":"strawberry","meaning":"딸기","partOfSpeech":"n.","example":"The children picked a ripe strawberry from the garden and shared it.","exampleTranslation":"아이들은 정원에서 잘 익은 딸기 하나를 따서 나눠 먹었습니다.","level":21,"category":"빈도 학습"},{"id":16612,"term":"stun","meaning":"기절시키다; 깜짝 놀라게 하다","partOfSpeech":"v.","example":"The loud explosion was enough to stun everyone nearby.","exampleTranslation":"그 큰 폭발음은 근처에 있던 모든 사람을 기절시키기에 충분했습니다.","level":21,"category":"빈도 학습"},{"id":16613,"term":"subsidy","meaning":"보조금","partOfSpeech":"n.","example":"The government offers a subsidy to farmers who grow organic crops.","exampleTranslation":"정부는 유기농 작물을 재배하는 농부들에게 보조금을 지급합니다.","level":21,"category":"빈도 학습"},{"id":16614,"term":"subtle","meaning":"미묘한; 은은한","partOfSpeech":"adj.","example":"There was a subtle change in her tone that only close friends noticed.","exampleTranslation":"그녀의 말투에는 가까운 친구들만 알아챌 수 있는 미묘한 변화가 있었습니다.","level":21,"category":"빈도 학습"},{"id":16615,"term":"suck","meaning":"빨다; 빨아들이다","partOfSpeech":"v.","example":"The baby began to suck on her thumb while falling asleep.","exampleTranslation":"아기는 잠들면서 엄지손가락을 빨기 시작했습니다.","level":21,"category":"빈도 학습"},{"id":16616,"term":"super","meaning":"아주 좋은; 굉장한","partOfSpeech":"adj.","example":"Everyone agreed that the birthday party was absolutely super.","exampleTranslation":"모두가 그 생일 파티가 정말 굉장했다고 입을 모았습니다.","level":21,"category":"빈도 학습"},{"id":16617,"term":"suspicion","meaning":"의심","partOfSpeech":"n.","example":"The police officer had a suspicion that the man was lying.","exampleTranslation":"경찰관은 그 남자가 거짓말을 하고 있다는 의심이 들었습니다.","level":21,"category":"빈도 학습"},{"id":16618,"term":"swallow","meaning":"삼키다","partOfSpeech":"v.","example":"The pill was so large that she found it hard to swallow.","exampleTranslation":"알약이 너무 커서 그녀는 삼키기가 힘들었습니다.","level":21,"category":"빈도 학습"},{"id":16619,"term":"sword","meaning":"검; 칼","partOfSpeech":"n.","example":"The knight raised his sword before entering the battle.","exampleTranslation":"그 기사는 전투에 들어가기 전에 검을 들어 올렸습니다.","level":21,"category":"빈도 학습"},{"id":16620,"term":"tease","meaning":"놀리다","partOfSpeech":"v.","example":"Older kids sometimes tease younger ones about their height.","exampleTranslation":"나이 많은 아이들은 가끔 어린아이들의 키를 놀립니다.","level":21,"category":"빈도 학습"},{"id":16621,"term":"teenage","meaning":"십대의","partOfSpeech":"adj.","example":"Many teenage students spend hours on their phones every day.","exampleTranslation":"많은 십대 학생들이 매일 몇 시간씩 휴대폰을 사용합니다.","level":21,"category":"빈도 학습"},{"id":16622,"term":"tempt","meaning":"유혹하다","partOfSpeech":"v.","example":"The smell of fresh bread was enough to tempt him into the bakery.","exampleTranslation":"갓 구운 빵 냄새는 그를 빵집으로 유혹하기에 충분했습니다.","level":21,"category":"빈도 학습"},{"id":16623,"term":"tense","meaning":"긴장된","partOfSpeech":"adj.","example":"The atmosphere in the courtroom grew tense as the verdict was announced.","exampleTranslation":"판결이 발표되자 법정 안 분위기가 긴장되었습니다.","level":21,"category":"빈도 학습"},{"id":16624,"term":"thief","meaning":"도둑","partOfSpeech":"n.","example":"A thief broke into the store and stole several laptops.","exampleTranslation":"도둑이 가게에 침입해 노트북 여러 대를 훔쳤습니다.","level":21,"category":"빈도 학습"},{"id":16625,"term":"suburb","meaning":"교외","partOfSpeech":"n.","example":"They moved from the city center to a quiet suburb to raise their kids.","exampleTranslation":"그들은 아이들을 기르기 위해 도심에서 조용한 교외로 이사했습니다.","level":22,"category":"빈도 학습"},{"id":16626,"term":"succession","meaning":"연속; 계승","partOfSpeech":"n.","example":"The team won five games in succession without a single loss.","exampleTranslation":"그 팀은 한 번도 지지 않고 다섯 경기를 연속으로 이겼습니다.","level":22,"category":"빈도 학습"},{"id":16627,"term":"suicide","meaning":"자살","partOfSpeech":"n.","example":"The documentary explored how better support can prevent suicide among teenagers.","exampleTranslation":"그 다큐멘터리는 더 나은 지원이 어떻게 십대의 자살을 예방할 수 있는지 다루었습니다.","level":22,"category":"빈도 학습"},{"id":16628,"term":"summit","meaning":"정상에 오르다; (산을) 정복하다","partOfSpeech":"v.","example":"The climbers hoped to summit the mountain before the storm arrived.","exampleTranslation":"등반가들은 폭풍이 오기 전에 산 정상에 오르기를 바랐습니다.","level":22,"category":"빈도 학습"},{"id":16629,"term":"superior","meaning":"우수한; 상급의","partOfSpeech":"adj.","example":"This fabric is superior in quality to the one we used last year.","exampleTranslation":"이 원단은 작년에 사용한 것보다 품질이 우수합니다.","level":22,"category":"빈도 학습"},{"id":16630,"term":"supervise","meaning":"감독하다","partOfSpeech":"v.","example":"A senior engineer will supervise the construction of the new bridge.","exampleTranslation":"선임 엔지니어가 새 다리 건설을 감독할 것입니다.","level":22,"category":"빈도 학습"},{"id":16631,"term":"supreme","meaning":"최고의","partOfSpeech":"adj.","example":"Winning the championship was the supreme achievement of her career.","exampleTranslation":"챔피언십에서 우승한 것은 그녀 경력의 최고 업적이었습니다.","level":22,"category":"빈도 학습"},{"id":16632,"term":"sweat","meaning":"땀을 흘리다","partOfSpeech":"v.","example":"Workers began to sweat heavily under the midday sun.","exampleTranslation":"일꾼들은 한낮의 태양 아래에서 심하게 땀을 흘리기 시작했습니다.","level":22,"category":"빈도 학습"},{"id":16633,"term":"swell","meaning":"부풀다; 붓다","partOfSpeech":"v.","example":"Her ankle began to swell soon after she twisted it.","exampleTranslation":"발목을 삔 직후 그녀의 발목이 붓기 시작했습니다.","level":22,"category":"빈도 학습"},{"id":16634,"term":"sympathy","meaning":"동정; 공감","partOfSpeech":"n.","example":"Neighbors sent flowers to show their sympathy after the accident.","exampleTranslation":"이웃들은 사고 이후 공감을 표하기 위해 꽃을 보냈습니다.","level":22,"category":"빈도 학습"},{"id":16635,"term":"tactic","meaning":"전술; 전략","partOfSpeech":"n.","example":"Changing the pricing was a smart tactic to attract new customers.","exampleTranslation":"가격을 바꾸는 것은 새 고객을 끌어들이기 위한 영리한 전략이었습니다.","level":22,"category":"빈도 학습"},{"id":16636,"term":"terror","meaning":"공포","partOfSpeech":"n.","example":"The children screamed in terror when the lights suddenly went out.","exampleTranslation":"불이 갑자기 꺼지자 아이들은 공포에 질려 비명을 질렀습니다.","level":22,"category":"빈도 학습"},{"id":16637,"term":"thereby","meaning":"그렇게 함으로써","partOfSpeech":"adv.","example":"She finished the project early, thereby impressing her manager.","exampleTranslation":"그녀는 프로젝트를 일찍 끝냈고, 그렇게 함으로써 상사에게 깊은 인상을 남겼습니다.","level":22,"category":"빈도 학습"},{"id":16638,"term":"thorough","meaning":"철저한","partOfSpeech":"adj.","example":"The inspector did a thorough check of every room before approval.","exampleTranslation":"검사관은 승인 전에 모든 방을 철저히 점검했습니다.","level":22,"category":"빈도 학습"},{"id":16639,"term":"thrill","meaning":"설레게 하다; 짜릿하게 하다","partOfSpeech":"v.","example":"The roller coaster ride never fails to thrill visitors of all ages.","exampleTranslation":"그 롤러코스터는 모든 연령대의 방문객을 언제나 짜릿하게 합니다.","level":22,"category":"빈도 학습"},{"id":16640,"term":"tide","meaning":"조수; 물결","partOfSpeech":"n.","example":"The tide was so high that the beach almost disappeared.","exampleTranslation":"조수가 너무 높아서 해변이 거의 사라질 정도였습니다.","level":22,"category":"빈도 학습"},{"id":16641,"term":"tin","meaning":"주석; 양철통","partOfSpeech":"n.","example":"She stored homemade cookies in an old tin.","exampleTranslation":"그녀는 집에서 만든 쿠키를 오래된 양철통에 보관했습니다.","level":22,"category":"빈도 학습"},{"id":16642,"term":"toast","meaning":"건배하다; (빵을) 굽다","partOfSpeech":"v.","example":"Everyone raised their glasses to toast the newlyweds.","exampleTranslation":"모두가 신랑 신부를 위해 건배하려고 잔을 들었습니다.","level":22,"category":"빈도 학습"},{"id":16643,"term":"toe","meaning":"발가락","partOfSpeech":"n.","example":"He stubbed his toe on the corner of the bed.","exampleTranslation":"그는 침대 모서리에 발가락을 부딪혔습니다.","level":22,"category":"빈도 학습"},{"id":16644,"term":"toilet","meaning":"화장실","partOfSpeech":"n.","example":"Excuse me, could you tell me where the toilet is?","exampleTranslation":"실례합니다, 화장실이 어디 있는지 알려주시겠어요?","level":22,"category":"빈도 학습"},{"id":16645,"term":"tomato","meaning":"토마토","partOfSpeech":"n.","example":"She sliced a fresh tomato for the salad.","exampleTranslation":"그녀는 샐러드에 넣을 신선한 토마토를 썰었습니다.","level":22,"category":"빈도 학습"},{"id":16646,"term":"ton","meaning":"톤(무게 단위)","partOfSpeech":"n.","example":"The truck can carry up to one ton of cargo.","exampleTranslation":"그 트럭은 최대 1톤의 화물을 실을 수 있습니다.","level":22,"category":"빈도 학습"},{"id":16647,"term":"toss","meaning":"던지다","partOfSpeech":"v.","example":"He decided to toss the old newspapers into the recycling bin.","exampleTranslation":"그는 오래된 신문을 재활용 통에 던져 넣기로 했습니다.","level":22,"category":"빈도 학습"},{"id":16648,"term":"towel","meaning":"수건","partOfSpeech":"n.","example":"She wrapped her wet hair in a towel after the shower.","exampleTranslation":"그녀는 샤워 후 젖은 머리를 수건으로 감쌌습니다.","level":22,"category":"빈도 학습"},{"id":16649,"term":"tragedy","meaning":"비극","partOfSpeech":"n.","example":"The play tells the tragedy of a king who loses everything he loves.","exampleTranslation":"그 연극은 사랑하는 모든 것을 잃는 왕의 비극을 다룹니다.","level":22,"category":"빈도 학습"},{"id":16650,"term":"transact","meaning":"거래하다","partOfSpeech":"v.","example":"Many customers prefer to transact business online these days.","exampleTranslation":"요즘 많은 고객들은 온라인으로 거래하는 것을 선호합니다.","level":22,"category":"빈도 학습"},{"id":16651,"term":"transmit","meaning":"전송하다; 전달하다","partOfSpeech":"v.","example":"The antenna can transmit signals over long distances.","exampleTranslation":"그 안테나는 신호를 먼 거리까지 전송할 수 있습니다.","level":22,"category":"빈도 학습"},{"id":16652,"term":"tray","meaning":"쟁반","partOfSpeech":"n.","example":"The waiter carried a tray full of drinks to the table.","exampleTranslation":"웨이터는 음료가 가득한 쟁반을 탁자로 날랐습니다.","level":22,"category":"빈도 학습"},{"id":16653,"term":"treasure","meaning":"소중히 여기다","partOfSpeech":"v.","example":"She will always treasure the necklace her grandmother gave her.","exampleTranslation":"그녀는 할머니가 준 목걸이를 항상 소중히 여길 것입니다.","level":22,"category":"빈도 학습"},{"id":16654,"term":"trunk","meaning":"(자동차) 트렁크; 나무 줄기","partOfSpeech":"n.","example":"He put the suitcase in the trunk of the car.","exampleTranslation":"그는 여행 가방을 자동차 트렁크에 실었습니다.","level":22,"category":"빈도 학습"},{"id":16655,"term":"weed","meaning":"잡초","partOfSpeech":"n.","example":"A stubborn weed kept growing between the bricks.","exampleTranslation":"고집스러운 잡초 하나가 벽돌 사이에서 계속 자라났습니다.","level":22,"category":"빈도 학습"},{"id":16656,"term":"whip","meaning":"휘젓다; 채찍질하다","partOfSpeech":"v.","example":"The recipe says to whip the cream until it forms soft peaks.","exampleTranslation":"조리법에는 크림이 부드러운 뿔 모양이 될 때까지 휘저으라고 되어 있습니다.","level":22,"category":"빈도 학습"},{"id":16657,"term":"yourself","meaning":"너 자신","partOfSpeech":"pron.","example":"You should be proud of yourself for finishing the race.","exampleTranslation":"완주한 것에 대해 스스로를 자랑스러워해야 합니다.","level":22,"category":"빈도 학습"},{"id":16658,"term":"treaty","meaning":"조약","partOfSpeech":"n.","example":"The two nations signed a peace treaty after years of conflict.","exampleTranslation":"두 나라는 오랜 분쟁 끝에 평화 조약에 서명했습니다.","level":23,"category":"빈도 학습"},{"id":16659,"term":"tremendous","meaning":"엄청난","partOfSpeech":"adj.","example":"The charity event raised a tremendous amount of money for the hospital.","exampleTranslation":"그 자선 행사는 병원을 위해 엄청난 금액을 모았습니다.","level":23,"category":"빈도 학습"},{"id":16660,"term":"tribe","meaning":"부족","partOfSpeech":"n.","example":"The documentary followed a tribe living deep in the rainforest.","exampleTranslation":"그 다큐멘터리는 열대 우림 깊은 곳에 사는 한 부족을 따라갔습니다.","level":23,"category":"빈도 학습"},{"id":16661,"term":"triumph","meaning":"승리하다; 이기다","partOfSpeech":"v.","example":"The underdog team managed to triumph over the defending champions.","exampleTranslation":"약체 팀이 디펜딩 챔피언을 상대로 승리를 거두었습니다.","level":23,"category":"빈도 학습"},{"id":16662,"term":"tunnel","meaning":"터널","partOfSpeech":"n.","example":"Workers spent two years digging the tunnel through the mountain.","exampleTranslation":"인부들은 산을 관통하는 터널을 파는 데 2년을 보냈습니다.","level":23,"category":"빈도 학습"},{"id":16663,"term":"ultimate","meaning":"궁극적인; 최고의","partOfSpeech":"adj.","example":"Winning the World Cup is every player's ultimate dream.","exampleTranslation":"월드컵 우승은 모든 선수의 궁극적인 꿈입니다.","level":23,"category":"빈도 학습"},{"id":16664,"term":"unity","meaning":"통합; 단결","partOfSpeech":"n.","example":"The speech called for unity among all the different political parties.","exampleTranslation":"그 연설은 여러 정당들 간의 단결을 촉구했습니다.","level":23,"category":"빈도 학습"},{"id":16665,"term":"utility","meaning":"공공요금; 유용성","partOfSpeech":"n.","example":"The utility bill this month was higher because of the cold weather.","exampleTranslation":"이번 달 공공요금은 추운 날씨 때문에 더 많이 나왔습니다.","level":23,"category":"빈도 학습"},{"id":16666,"term":"vague","meaning":"모호한; 막연한","partOfSpeech":"adj.","example":"His answer was too vague for the interviewer to understand.","exampleTranslation":"그의 답변은 면접관이 이해하기에 너무 모호했습니다.","level":23,"category":"빈도 학습"},{"id":16667,"term":"valid","meaning":"유효한","partOfSpeech":"adj.","example":"Your passport must be valid for at least six months to travel.","exampleTranslation":"여행을 하려면 여권이 최소 6개월 이상 유효해야 합니다.","level":23,"category":"빈도 학습"},{"id":16668,"term":"violate","meaning":"위반하다; 어기다","partOfSpeech":"v.","example":"Dumping chemicals into the river would violate environmental laws.","exampleTranslation":"강에 화학 물질을 버리는 것은 환경법을 위반하는 것입니다.","level":23,"category":"빈도 학습"},{"id":16669,"term":"virtual","meaning":"가상의","partOfSpeech":"adj.","example":"Many students now attend virtual classes from home.","exampleTranslation":"많은 학생들이 이제 집에서 가상 수업을 듣습니다.","level":23,"category":"빈도 학습"},{"id":16670,"term":"virtue","meaning":"미덕","partOfSpeech":"n.","example":"Patience is considered a virtue in most cultures.","exampleTranslation":"인내심은 대부분의 문화에서 미덕으로 여겨집니다.","level":23,"category":"빈도 학습"},{"id":16671,"term":"vulnerable","meaning":"취약한; 상처받기 쉬운","partOfSpeech":"adj.","example":"Elderly people are more vulnerable to extreme heat.","exampleTranslation":"노인들은 극심한 더위에 더 취약합니다.","level":23,"category":"빈도 학습"},{"id":16672,"term":"whistle","meaning":"휘파람을 불다","partOfSpeech":"v.","example":"He likes to whistle a happy tune while walking to work.","exampleTranslation":"그는 출근길에 걸으며 즐거운 곡조로 휘파람 부는 것을 좋아합니다.","level":23,"category":"빈도 학습"},{"id":16673,"term":"wicked","meaning":"사악한; 못된","partOfSpeech":"adj.","example":"The wicked witch in the story tricked everyone in the village.","exampleTranslation":"이야기 속 사악한 마녀는 마을 사람들 모두를 속였습니다.","level":23,"category":"빈도 학습"},{"id":16674,"term":"wolf","meaning":"게걸스럽게 먹다","partOfSpeech":"v.","example":"After the long hike, he could easily wolf down two sandwiches.","exampleTranslation":"긴 등산 후 그는 샌드위치 두 개를 순식간에 먹어치울 수 있었습니다.","level":23,"category":"빈도 학습"},{"id":16675,"term":"wool","meaning":"양모; 털실","partOfSpeech":"n.","example":"This sweater is made from pure wool and keeps you very warm.","exampleTranslation":"이 스웨터는 순수한 양모로 만들어져 아주 따뜻합니다.","level":23,"category":"빈도 학습"},{"id":16676,"term":"worm","meaning":"지렁이; 벌레","partOfSpeech":"n.","example":"A worm crawled slowly across the wet sidewalk after the rain.","exampleTranslation":"비가 온 뒤 지렁이 한 마리가 젖은 보도를 천천히 기어갔습니다.","level":23,"category":"빈도 학습"},{"id":16677,"term":"yell","meaning":"소리치다; 외치다","partOfSpeech":"v.","example":"The coach had to yell instructions over the noise of the crowd.","exampleTranslation":"코치는 관중의 소음 속에서 지시 사항을 큰 소리로 외쳐야 했습니다.","level":23,"category":"빈도 학습"},{"id":16678,"term":"zero","meaning":"0의; 전혀 없는","partOfSpeech":"adj.","example":"The team ended the season with zero losses.","exampleTranslation":"그 팀은 패배가 하나도 없이 시즌을 마쳤습니다.","level":23,"category":"빈도 학습"},{"id":16679,"term":"booking","meaning":"예약","partOfSpeech":"n.","example":"Please confirm your booking at least 24 hours before arrival.","exampleTranslation":"도착 최소 24시간 전에 예약을 확인해 주세요.","level":24,"category":"빈도 학습"},{"id":16680,"term":"evenly","meaning":"고르게; 균등하게","partOfSpeech":"adv.","example":"Spread the sauce evenly over the pizza dough before baking.","exampleTranslation":"굽기 전에 피자 반죽 위에 소스를 고르게 펴 바르세요.","level":26,"category":"빈도 학습"},{"id":16681,"term":"furnish","meaning":"가구를 비치하다; 제공하다","partOfSpeech":"v.","example":"They plan to furnish the new apartment with secondhand furniture.","exampleTranslation":"그들은 중고 가구로 새 아파트를 꾸밀 계획입니다.","level":28,"category":"빈도 학습"},{"id":16682,"term":"lively","meaning":"활기찬; 생기 넘치는","partOfSpeech":"adj.","example":"The market was lively with vendors shouting and music playing.","exampleTranslation":"시장은 상인들의 외침과 음악 소리로 활기가 넘쳤습니다.","level":30,"category":"빈도 학습"},{"id":16684,"term":"presently","meaning":"현재; 지금","partOfSpeech":"adv.","example":"The manager is presently out of the office but will return soon.","exampleTranslation":"관리자는 현재 사무실에 없지만 곧 돌아올 것입니다.","level":34,"category":"빈도 학습"},{"id":16685,"term":"weave","meaning":"짜다; 엮다","partOfSpeech":"v.","example":"Skilled workers weave cotton threads into colorful fabric.","exampleTranslation":"숙련된 일꾼들은 면실을 엮어 알록달록한 천을 만듭니다.","level":36,"category":"빈도 학습"},{"id":16686,"term":"seasoning","meaning":"양념; 조미료","partOfSpeech":"n.","example":"The chef added a pinch of seasoning to bring out the flavor.","exampleTranslation":"요리사는 풍미를 살리기 위해 양념을 한 꼬집 넣었습니다.","level":37,"category":"빈도 학습"},{"id":16687,"term":"utterly","meaning":"완전히; 철저히","partOfSpeech":"adv.","example":"She felt utterly exhausted after finishing the marathon.","exampleTranslation":"그녀는 마라톤을 완주한 후 완전히 지쳐 버렸습니다.","level":40,"category":"빈도 학습"},{"id":16688,"term":"fin","meaning":"지느러미","partOfSpeech":"n.","example":"The shark's fin broke the surface of the water.","exampleTranslation":"상어의 지느러미가 수면 위로 드러났습니다.","level":43,"category":"빈도 학습"},{"id":16689,"term":"pant","meaning":"헐떡거리다","partOfSpeech":"v.","example":"The dog began to pant heavily after chasing the ball.","exampleTranslation":"그 개는 공을 쫓아다닌 후 심하게 헐떡거리기 시작했습니다.","level":46,"category":"빈도 학습"},{"id":16690,"term":"stranded","meaning":"고립된; 오도 가도 못하는","partOfSpeech":"adj.","example":"The hikers were stranded on the mountain when the storm hit.","exampleTranslation":"폭풍이 닥쳤을 때 등산객들은 산에서 고립되었습니다.","level":49,"category":"빈도 학습"}]`);export{e as default};